// AUTO-GENERATED — infos groupements scrapées (description + contacts + actualités) — 2026-07-17
// norm(nom) -> {type,description,site,email,tel,adresse,region,nbAdherents,dirigeants[],actualites[]}
window.GRP_INFO = {"37degrsmasant":{"type":"groupement / coopérative de pharmaciens indépendants","description":"Groupement de pharmaciens indépendants né de la structure Syntrophie, positionné sur les solutions naturelles, le maintien à domicile et l'OTC, autour de valeurs d'éthique, d'entraide et de transparence. Réunit environ 60 à 76 officines indépendantes, principalement en Auvergne-Rhône-Alpes. Propose une application patient (envoi d'ordonnance en amont) et un accompagnement de proximité.","site":"https://37degres-masante.fr/","tel":"04 77 74 14 14","adresse":"Panissières (Loire, 42)","region":"Auvergne-Rhône-Alpes","nbAdherents":"~63 à 76 officines","dirigeants":[{"nom":"Alexandre Lassakeur","fn":"Président"},{"nom":"Antoine Ciolino","fn":"Administrateur"},{"nom":"Franck Beretta","fn":"Administrateur"},{"nom":"Julien Verchère","fn":"Administrateur"},{"nom":"Sandra Carbonneau","fn":"Administratrice"}],"actualites":[{"titre":"Groupement créé par la structure Syntrophie (rebranding en 37 degrés ma santé)","date":"","source":"Le Moniteur des Pharmacies"},{"titre":"Séminaire annuel du groupement et développement de l'app patient","date":"","source":"LinkedIn 37 degrés ma santé"}]},"agirpharmacyal":{"type":"confédération de groupements régionaux (Agir Pharma) + groupement régional membre (Pharmacyal)","description":"Agir Pharma est une confédération de groupements régionaux de pharmaciens créée en 2014, structurée en SAS, réunissant environ 5 groupements et ~450 officines et attachée à l'indépendance et à la dimension humaine/régionale de ses membres (dont PUC Pharma, Mutualpharm, Pharmacyal, Cap'Unipharm). Pharmacyal est l'un de ses groupements membres : ~96 adhérents surtout implantés dans les Hauts-de-France (Nord-Pas-de-Calais), CA moyen ~1,5 M€, basé à Roubaix.","site":"https://www.pharmacyal.com/","adresse":"Pharmacyal : Roubaix (Nord)","region":"National (confédération) ; Pharmacyal = Hauts-de-France","nbAdherents":"Agir Pharma ~450 officines / 5 groupements ; Pharmacyal ~96 adhérents","actualites":[{"titre":"Agir Pharma se structure en SAS","date":"","source":"Le Moniteur des Pharmacies (n-3272)"},{"titre":"Agir Pharma se lance dans le courtage","date":"","source":"Le Quotidien du Pharmacien"},{"titre":"Carte de fidélité lancée chez Pharmacyal","date":"","source":"Le Moniteur des Pharmacies"}]},"aptiphar":{"type":"groupement d'achat / groupement de pharmaciens indépendants (Groupe AEPK)","description":"Groupement économique de pharmaciens indépendants créé en 1987 à l'initiative de pharmaciens de la communauté cambodgienne réunis dans l'association AEPK. Il permet à chaque adhérent de conserver son indépendance tout en bénéficiant de conditions d'achat optimisées, la gestion étant assurée par des professionnels de la pharmacie. Réunit aujourd'hui plus de 110 officines, principalement en Île-de-France, autour des valeurs d'excellence, d'indépendance et d'innovation.","site":"https://aptiphar.fr/","region":"Île-de-France (principalement)","nbAdherents":"plus de 110 officines"},"capunipharm":{"type":"coopérative / centrale d'achat de pharmaciens (membre d'Agir Pharma)","description":"Groupement coopératif régional et centrale d'achat de pharmaciens d'officine créé en janvier 2013, certifié ISO 9001:2015, membre de la confédération Agir Pharma. Basé à Blanquefort (Gironde, Aquitaine), il compte ~94 adhérents et négocie avec ~110 laboratoires partenaires. Dispose d'un site logistique conforme aux normes ANSM sous responsabilité pharmacien, d'un outil de commande intranet, du logiciel OFFISANTE, de formations et de sa MDD Pharma Soins.","site":"https://capunipharm.fr/","tel":"05 56 35 12 47","adresse":"7 rue Pierre et Marie Curie, 33290 Blanquefort","region":"Nouvelle-Aquitaine (Gironde)","nbAdherents":"~94 adhérents"},"elitpharma":{"type":"groupement / réseau d'achat de pharmaciens indépendants","description":"Groupement fondé en 2010 par deux pharmaciens pour créer une structure d'entraide et fédérer les petites et moyennes officines face à la concurrence, en mutualisant leurs forces et en défendant leurs intérêts. Basé à Sarcelles (Val-d'Oise), il propose accompagnement marketing/communication (site web avec Click&Collect) et optimisation des marges/achats.","site":"https://elitpharma.fr/","adresse":"26 avenue du 8 mai 1945, 95200 Sarcelles","region":"Île-de-France (siège) / national"},"filieris":{"type":"groupe de santé mutualiste (régime minier) — PAS un groupement d'achat classique","description":"Filieris est le groupe de santé du régime minier (offre de soins mutualiste), qui accueille plus de 210 000 personnes par an dans plus de 200 lieux (centres et établissements de santé, Ehpad, SSIAD, centres optiques, laboratoires) et exploite un réseau d'environ 18 pharmacies mutualistes réparties sur ses territoires. Il ne s'agit pas d'un groupement d'achat d'officines indépendantes mais d'un réseau intégré de pharmacies mutualistes (historiquement ouvertes aux affiliés du régime minier), avec service de portage de médicaments à domicile.","site":"https://www.filieris.fr/","region":"National (bassins miniers)","nbAdherents":"~18 pharmacies mutualistes (réseau intégré)","actualites":[{"titre":"Modèle des pharmacies mutualistes fragilisé — les officines mutualistes jouent leur survie","date":"2026","source":"Revue Pharma / Le Quotidien du Pharmacien"}]},"groupeuniverspharmacie":{"type":"groupement / enseigne de pharmacies (avec centrale de référencement)","description":"Réseau international de pharmacies fédérées structuré autour des enseignes Univers Pharmacie et Forum Santé, avec une centrale de référencement d'environ 595 officines. Le groupe compte ~152 pharmacies sous enseigne Univers Pharmacie et ~32 sous Forum Santé, et a fortement grandi (de ~240 à ~450 pharmacies) via l'acquisition de nouveaux groupements. Basé à Colmar, il fournit coaching mensuel en officine, formations certifiées, congrès et séminaires.","site":"https://groupeuniverspharmacie.com/","adresse":"Colmar (Haut-Rhin)","region":"National (siège Colmar, Grand Est)","nbAdherents":"~450 pharmacies (dont ~152 Univers Pharmacie, ~32 Forum Santé) ; ~595 en centrale de référencement","dirigeants":[{"nom":"Daniel Buchinger","fn":"Président / dirigeant"}],"actualites":[{"titre":"Le groupe a acquis deux nouveaux groupements (croissance de ~240 à ~450 pharmacies)","date":"","source":"Le Moniteur des Pharmacies"}]},"ladhmpharma":{"type":"groupement d'achat / structure de regroupement à l'achat (SAS)","description":"Structure de regroupement à l'achat (SAS) créée en 2021, dédiée à l'achat groupé, au stockage et à la distribution de médicaments et produits parapharmaceutiques pour le compte de ses officines adhérentes, avec plateforme de commande B2B en ligne (gérée par Itekpharma). Basée à Cohade (Haute-Loire, Auvergne-Rhône-Alpes), capital ~18 450 €. Détails d'adhérents et de dirigeants non publiés sur le site.","site":"https://ladhm-pharma.com/","adresse":"Rue du Breuil, 43100 Cohade","region":"Auvergne-Rhône-Alpes (Haute-Loire)"},"magdalon":{"type":"groupement de pharmacies (adossé à Hygie31)","description":"Groupement de pharmacies fondé en 2020 à Strasbourg, réunissant plus de 105 officines majoritairement dans le Grand Est, pour un CA cumulé d'environ 250 M€. Il accompagne les officines (3 visites/an, conseil, formation, optimisation des conditions commerciales, aide aux projets de cession/transmission). Passé début 2024 dans le giron du groupe toulousain Hygie31 (Lafayette).","site":"https://magdaleon.fr/","adresse":"Strasbourg (Bas-Rhin)","region":"Grand Est (siège Strasbourg)","nbAdherents":"plus de 105 officines","dirigeants":[{"nom":"Jean-Marc Gauche","fn":"Cofondateur"},{"nom":"Constant Kuder","fn":"Cofondateur"},{"nom":"Christian Zimmermann","fn":"Cofondateur"}],"actualites":[{"titre":"Magdaléon entre dans le giron du toulousain Hygie31 (partenariat/rapprochement)","date":"2024-01","source":"Le Moniteur des Pharmacies / Gazette du Midi"}]},"objectifpharma":{"type":"groupement / enseigne (Coopérative Welcoop) — devenu Wellpharma","description":"Groupement de pharmaciens né en 2009 de la fusion de Pharm'Objectif et Pharma Moselle, affilié à la Coopérative Welcoop (coopérative détenue à 100% par des pharmaciens). Il accompagne plus de 450 officines affiliées (gestion, formation, achats, trade marketing, suivi patient) dans le respect de l'indépendance du pharmacien. L'enseigne a évolué et s'aligne désormais sous la marque Wellpharma.","site":"https://www.objectif-pharma.com/","region":"National (Welcoop, siège Nancy/Grand Est)","nbAdherents":"plus de 450 pharmacies affiliées","actualites":[{"titre":"Objectif Pharma devient Wellpharma (alignement de marque)","date":"","source":"La Coopérative Welcoop"},{"titre":"Objectif Pharma dévoile ses stratégies et innovations pour 2025","date":"2025","source":"Le Quotidien du Pharmacien"}]},"parispharma":{"type":"groupement de pharmaciens — ancien nom, devenu Aprium Pharmacie","description":"Paris Pharma était un groupement régional de pharmaciens d'officine (créé en 2006 par Healthy Group). Il a changé de nom et fusionné avec d'autres groupements régionaux (Pacapharma, Rhône-Alpes Pharma, Sud-Ouest Pharma, Nordpharma, Estpharma) pour former Aprium Pharmacie, réseau national d'environ 470 pharmacies réalisant ~1,6 Md€ de CA. À traiter aujourd'hui comme Aprium Pharmacie.","site":"https://www.aprium-pharmacie.fr/","region":"Île-de-France (origine) / national (Aprium)","nbAdherents":"Aprium ~470 pharmacies","dirigeants":[{"nom":"Laurent Keiser","fn":"Président Aprium (présidence tournante, depuis fév. 2022)"},{"nom":"Alain Hababou","fn":"Vice-Président Aprium (ancien Président)"}],"actualites":[{"titre":"Paris Pharma change de nom et fusionne pour devenir Aprium Pharmacie","date":"","source":"Le Quotidien du Pharmacien"},{"titre":"Présidence tournante : Laurent Keiser nommé président d'Aprium","date":"2022-02","source":"Wikipédia / Aprium"}]},"pharma10":{"type":"coopérative de pharmaciens avec centrale d'achat","description":"Groupement coopératif de pharmaciens indépendants avec sa propre centrale d'achat sous responsabilité pharmacien, basé à Romilly-sur-Seine (Aube), fort de plus de 25 ans d'expérience. Capital 100% détenu par les pharmaciens coopérateurs (plus de 140 coopérateurs, >140 laboratoires partenaires), officines réparties sur 21 départements. Sans cotisation annuelle. Catalogue de >6 500 références, plus services (sites web, merchandising, e-learning, téléconsultation).","site":"https://www.pharma10.org/","adresse":"Romilly-sur-Seine (Aube, 10)","region":"Grand Est (Aube) / interrégional","nbAdherents":"plus de 140 pharmaciens coopérateurs (21 départements)"},"pharmabsolu":{"type":"groupement de pharmacies indépendantes","description":"Groupement de pharmacies indépendantes créé en juin 2012, proposant des solutions concrètes mêlant expertise, collaboration et engagement collectif (offres pharma/parapharma, matériel médical et maintien à domicile, promotions). Basé à Glatigny (Moselle, Grand Est).","site":"https://groupement-pharmabsolu.fr/","adresse":"14 rue des Vignottes, 57530 Glatigny","region":"Grand Est (Moselle)","dirigeants":[{"nom":"Arnaud Houbin","fn":"Président"}]},"pharmarem":{"type":"groupement d'achat de pharmaciens indépendants","description":"Groupement de pharmaciens indépendants créé en 2019, dont l'objet principal est d'optimiser les remises sur l'ensemble des achats (négociation des meilleures conditions commerciales auprès des laboratoires et grossistes-répartiteurs) tout en préservant la liberté et l'indépendance des titulaires. Réseau de plus d'une cinquantaine de points de vente répartis sur le territoire national.","region":"National","nbAdherents":"plus de 50 points de vente"},"positivepharma":{"type":"coopérative de pharmaciens (SAS à capital variable)","description":"Groupement coopératif de pharmaciens fonctionnant en SAS à capital variable (pharmacies actionnaires en parts sociales), créé il y a une dizaine d'années, basé à Vaulx-en-Velin (métropole de Lyon, Auvergne-Rhône-Alpes). Sans cotisation d'adhésion, il propose un diagnostic gratuit, des achats optimisés (génériques, laboratoires partenaires), des services (télémédecine, cartes de fidélité) et un accompagnement communication/merchandising de proximité.","tel":"04 78 31 41 37","adresse":"3 allée Camille Desmoulins, 69120 Vaulx-en-Velin","region":"Auvergne-Rhône-Alpes (Lyon)"},"smartpharma":{"type":"groupement de pharmaciens indépendants","description":"Groupement indépendant né d'un collectif de pharmaciens amis en Touraine, dont l'ambition est de fédérer, structurer et défendre les intérêts des officines par un réseau de proximité, des outils adaptés et un accompagnement quotidien. Se positionne explicitement à taille humaine (ni centrale déguisée, ni perte d'indépendance) avec une performance assumée et de la bienveillance. (Ne pas confondre avec le cabinet Smart Pharma Consulting, Paris.)","site":"https://smart-pharma.fr/","region":"Centre-Val de Loire (Touraine) / national"},"trentactiv":{"type":"groupement régional avec centrale d'achat (CentralActiv)","description":"Groupement régional de pharmaciens créé en 2008 (fusion de deux groupements informels), basé en Lot-et-Garonne, comptant ~41 officines adhérentes. Il a créé sa propre centrale d'achat CAP CentralActiv (250 m² à Saint-Étienne-de-Fougères) pour améliorer les conditions d'achat sur l'OTC, la parapharmacie et le matériel médical. Adhésion sans droit d'entrée, abonnement ~100 € HT/mois. Ouvert aux officines du Sud-Ouest.","site":"http://www.trentactiv.com/","adresse":"Saint-Étienne-de-Fougères (Lot-et-Garonne)","region":"Nouvelle-Aquitaine (Lot-et-Garonne, Sud-Ouest)","nbAdherents":"~41 officines","actualites":[{"titre":"Trentactiv racheté par une confédération de dix acteurs (consolidation)","date":"","source":"Le Moniteur des Pharmacies"}]},"upsem":{"type":"possible union pharmaceutique belge (UPSEM = Union Pharmaceutique du Sud de l'Entre-Sambre-et-Meuse) — non confirmé comme groupement français","description":"Aucune information fiable confirmant un groupement de pharmacies FRANÇAIS nommé Upsem. La seule correspondance trouvée est UPSEM = Union Pharmaceutique du Sud de l'Entre-Sambre-et-Meuse, en Belgique, ce qui ne correspond pas au périmètre France. À vérifier / clarifier avant exploitation (potentielle erreur de saisie ou entité hors France)."},"7ortho":{"type":"groupement d'achat / SRA","description":"Petite structure de regroupement à l'achat basée à Manosque, dédiée aux produits pharmaceutiques, para-pharmaceutiques, orthopédie et matériel d'HAD destinés à la revente en officine. Structure locale réunissant quelques officines associées (Pharmacie du Bourguet, du Théâtre, Blanc, Les 4 Chemins...). Objectif : mutualiser les achats d'orthopédie et de matériel pour ses membres.","adresse":"Manosque (04100)","region":"Provence-Alpes-Côte d'Azur"},"agirpharma":{"type":"confédération / collectif de groupements","description":"Collectif fédérant plusieurs groupements régionaux (Cap'Unipharm, Excel Pharma, Les Officinales, Objectif Santé, Tag Pharm...) qui négocie au nom de plus de 500 officines pour garantir de bonnes conditions commerciales tout en préservant l'indépendance des pharmaciens. S'est aussi lancé dans le courtage (transaction d'officines). A fusionné avec Apsara.","adresse":"Bezannes (51430)","region":"National (siège rattaché à Bezannes, Grand Est)","actualites":[{"titre":"Fusion Apsara + Agir Pharma → création d'Apsagir, ~1 026 pharmacies et 14 groupements régionaux","date":"2023","source":"Le Quotidien du Pharmacien"},{"titre":"Agir Pharma accueille de nouvelles officines en Auvergne","source":"Le Quotidien du Pharmacien"},{"titre":"Agir Pharma se lance dans le courtage (transaction d'officines)","source":"Le Quotidien du Pharmacien"}]},"artisansant":{"type":"enseigne (du groupement Leadersanté)","description":"Enseigne du groupement Leadersanté pensée pour les pharmacies de proximité, avec un positionnement axé sur la naturalité et l'accompagnement du patient ('pharmaciens artisans'). Chaque officine garde son identité, son autonomie de gestion et sa liberté d'engagement. Au sein de Leadersanté (~330 officines), la marque Artisans Santé regroupait environ 35 points de vente.","region":"National","nbAdherents":"~35 officines sous l'enseigne Artisans Santé (Leadersanté ~330 officines)","actualites":[{"titre":"Les 25 officines Côté Pharma se rapprochent du groupement Leadersanté","source":"Le Moniteur des Pharmacies"}]},"ceido":{"type":"groupement de pharmaciens indépendants (modèle 'signature')","description":"Groupement créé en 1988 (Centre Européen d'Intérêt et de Développement de l'Officine) proposant un modèle 'signature' sans enseigne ni standardisation : le pharmacien reste totalement indépendant et différencie son image locale tout en profitant de la force du réseau. Plus de 200 conditions commerciales avec laboratoires et prestataires, accompagnement sur achats, visibilité locale, gestion et fidélisation.","site":"https://www.ceido.com/","region":"National","nbAdherents":"réseau d'officines indépendantes (>200 conditions commerciales négociées)"},"elsiegroupe":{"type":"enseigne / réseau des grandes officines (TOP 500)","description":"Réseau né en 2017 fédérant les plus grandes officines indépendantes de France (issues du TOP 500, ~500 m² en moyenne). Passé de 9 à plus de 250 officines en quelques années, spécialisé dans la distribution parapharmacie/OTC et le développement des nouveaux services de santé (dépistage, vaccination, télémédecine). 37e enseigne du top 100 LSA du commerce français en 2025.","site":"https://www.elsie-sante.fr/","region":"National","nbAdherents":"plus de 250 officines","actualites":[{"titre":"Lancement de la nouvelle enseigne SELIA PHARMA+","date":"2024-2025","source":"FCA / commerce-associe.fr"},{"titre":"Elsie Santé classée 37e enseigne du top 100 LSA de la distribution française","date":"2025","source":"Elsie Santé"}]},"flexipluspharma":{"type":"groupement / réseau régional (alliance Evecial)","description":"Réseau de pharmaciens indépendants créé en 2021 par Nicolas Lion, implanté sur la façade atlantique, comptant près de 70 officines adhérentes. Piliers : transparence, dynamisme, proximité, collaboration. Accompagne ses membres via un pool d'experts (achats, gestion, communication, merchandising, digitalisation, formation).","site":"https://www.flexipluspharma.fr/","adresse":"3 Rue de la Guifette Noire, 17137 Nieul-sur-Mer","region":"Façade atlantique (Nouvelle-Aquitaine / Pays de la Loire)","nbAdherents":"~70 officines","dirigeants":[{"nom":"Nicolas Lion","fn":"Fondateur / Directeur du groupement"}],"actualites":[{"titre":"Flexi Plus Pharma (avec Solipharm) rejoint l'alliance Evecial, qui atteint ~400 officines et >1,2 Md€ de CA (avec Boticinal, Dynamis, Ceido, Be Pharma, Solipharm)","date":"septembre 2024","source":"Evecial / Le Quotidien du Pharmacien"}]},"gpp":{"type":"groupement / réseau de pharmacies (G Plus Pharmacie)","description":"GPP correspond à G Plus Pharmacie, réseau créé en 2016 par 5 pharmaciens titulaires. Il regroupe plus de 25 pharmacies et environ 400 collaborateurs, avec une offre de services (livraison de matériel médical, dépistages, vaccination, gammes orthopédie / matériel médical / maternité-enfant). Valeurs affichées : respect, partage, excellence, satisfaction.","site":"https://gpluspharmacie.fr","region":"Non confirmée (mentions Auvergne-Rhône-Alpes / Nouvelle-Aquitaine ; adresse de gestion en Île-de-France, Chelles 77)","nbAdherents":"plus de 25 pharmacies (~400 collaborateurs)"},"hpitotum":{"type":"groupement de pharmaciens","description":"Totum Pharmaciens est l'émanation du groupement HPI (Humains, Professionnels et Innovants), créé en 2008. Réseau d'environ 200 à 300 officines en France qui mutualisent leurs compétences autour de services médicalisés certifiés (protocoles d'entretiens thérapeutiques, suivi de pathologies) et d'offres commerciales dynamiques. 'Totum' = approche globale de la santé / extrait complet d'une plante.","site":"https://www.totum.fr/","region":"National","nbAdherents":"~170 à 300 officines ; 75 laboratoires référencés","dirigeants":[{"nom":"Mehdi Djilani","fn":"Président"}]},"lafsant":{"type":"société de services / réseau d'enseignes (ex-Lafayette Conseil)","description":"Société de conseil et de services animant les enseignes Pharmacie Lafayette (~296 officines), Parapharmacie Lafayette, Optique Lafayette (~48 PDV) et Médical Lafayette (~38 PDV). A changé de nom (Lafayette Conseil → Laf Santé) pour affirmer son virage vers les missions de santé. Modèle 'prix bas toute l'année'. CA cumulé du réseau ~1,094 Md€ en 2023.","site":"https://lafsante.com/","tel":"05 61 57 86 23","adresse":"4 rue Brindejonc des Moulinais, 31500 Toulouse","region":"National (siège Toulouse, Occitanie)","nbAdherents":"~296 pharmacies Lafayette (+ optique et matériel médical)","actualites":[{"titre":"Changement de nom Lafayette Conseil → Groupe Laf Santé, recentrage sur les missions de santé","source":"Le Moniteur des Pharmacies"},{"titre":"CA cumulé du réseau ~1,094 milliard d'euros","date":"2023","source":"Laf Santé"}]},"majelis":{"type":"groupement de pharmacies (Elfimaje Majelis) + marque de produits","description":"Elfimaje Majelis est un groupement de pharmacies à portée régionale basé à Maubeuge (Hauts-de-France), proposant conditions labos (OTC, parapharmacie, génériques), formations, accords logiciels et plateformes d'achat (matériel médical, OTC, parapharmacie). Le collectif développe aussi sa propre gamme de produits Majelis (dermatologie, cosmétique, nutraceutique, incontinence).","tel":"09 52 48 08 77","adresse":"44 rue Émile Verhaeren, 59600 Maubeuge","region":"Hauts-de-France"},"officinalbyboticinal":{"type":"enseigne (du groupe Boticinal / alliance Evecial)","description":"Enseigne lancée en 2024, dérivée de la marque Boticinal (groupe fondé en 2016 par Florence et François Rochet), conçue pour les pharmacies de quartier positionnées 'expert santé et prévention' avec des gammes de produits naturels. S'appuie sur un programme de fidélité, un plan de trade, des campagnes marketing, des outils de gestion et de merchandising. Boticinal fait partie de l'alliance Evecial.","site":"https://officinalbyboticinal.com/","region":"National","dirigeants":[{"nom":"Florence Rochet","fn":"Co-fondatrice de Boticinal"},{"nom":"François Rochet","fn":"Co-fondateur de Boticinal"}],"actualites":[{"titre":"Lancement de la nouvelle enseigne Officinal by Boticinal pour les pharmacies de proximité","date":"2024","source":"Le Moniteur des Pharmacies"}]},"pharmprice":{"type":"enseigne discount parapharmacie / centrale d'achat (groupe Direct Labo)","description":"Concept d'enseigne créé en 2004 par Direct Labo, axé sur la parapharmacie à prix bas toute l'année en libre-service pour réduire la dépendance de l'officine au médicament. Réservé aux pharmaciens diplômés, il donne accès à la puissance d'achat d'une centrale même aux plus petites officines. Magasin pilote ouvert à Tremblay.","adresse":"20 rue Contrescarpe, Nantes","region":"National (siège Nantes, Pays de la Loire)"},"pharmadirect":{"type":"groupement / société coopérative à capital variable","description":"Groupement régional du Sud-Est (Var / Provence) créé en 1987, sous forme de société anonyme coopérative à capital variable, fonctionnant sur le principe de l'indépendance de chaque pharmacien. Environ 70 laboratoires référencés, cotisation annuelle sans indexation sur le CA, plateformes d'achat OTC et parapharmacie, accompagnement qualité.","site":"pharma-direct.fr","email":"centrale@pharma-direct.fr","tel":"04 98 12 19 76","adresse":"240 rue Georges Besse, 83600 Fréjus","region":"Provence-Alpes-Côte d'Azur (Var)","dirigeants":[{"nom":"Jean-Pierre Borel","fn":"Président"}]},"pharmarket":{"type":"enseigne + plateforme e-commerce (du groupement Cofisanté)","description":"Enseigne et site de vente en ligne créés par le groupement Cofisanté (fondé en 1995 par Bruno Métairie). Pharmarket regroupe plus de 100 officines partenaires en France (>250 pharmaciens) et permet de commander médicaments et parapharmacie en ligne avec livraison à domicile via une pharmacie française et conseil pharmacien.","site":"https://www.pharmarket.com/","region":"National","nbAdherents":">100 officines partenaires (~250 pharmaciens)","dirigeants":[{"nom":"Bruno Métairie","fn":"Fondateur du groupement Cofisanté"}]},"pyxis":{"type":"SRA (structure de regroupement à l'achat)","description":"Pyxis Pharma est une structure de regroupement à l'achat (SRA) créée en 2010 par deux titulaires, regroupant environ 250 pharmacies. Elle négocie achats, transport et stockage de médicaments non remboursables et autres marchandises pour ses membres (art. D5125-24-16 CSP). Adossée depuis novembre 2011 à la centrale d'achat pharmaceutique (CAP) Sagitta Pharma, à Tours, qui livre ~60 laboratoires référencés.","adresse":"Joué-lès-Tours (siège association) ; entrepôt Sagitta Pharma à Tours","region":"National (base logistique Tours / Joué-lès-Tours, Centre-Val de Loire)","nbAdherents":"~250 pharmacies ; ~60 laboratoires référencés"},"socopharma":{"type":"société coopérative pharmaceutique / groupement d'achat","description":"Société Coopérative Pharmaceutique à capital variable créée en 1970 à Valenciennes pour offrir aux pharmaciens de meilleures conditions d'achat et un poids accru dans les négociations avec les laboratoires. Travaille notamment avec les génériqueurs (Arrow, EG Labo, Viatris/Mylan, Sandoz, Zentiva) et propose des services en ligne ; partenariat avec AGETIP (2003) pour le tiers payant.","adresse":"13 avenue du Sénateur Girard, 59300 Valenciennes","region":"Hauts-de-France"},"upa":{"type":"groupement / GIE régional (partenaire Astera-CERP)","description":"UPA (Union Pharmaceutique d'Armor), devenue Les Pharmaciens d'Armor, est l'un des plus anciens groupements de France, fondé en 1964 à l'initiative de Louis Lecoq (pharmacien à Vannes). Structuré en GIE, il mutualise les achats et services tout en préservant l'indépendance de ses membres, avec un accompagnement qualité dans le cadre de son partenariat avec la coopérative Astera (adossée au répartiteur CERP).","site":"https://www.upa.bzh/","region":"Bretagne / Grand Ouest","dirigeants":[{"nom":"Louis Lecoq","fn":"Fondateur (1964)"}]},"vpharma":{"type":"réseau coopératif de pharmacies (BELGE, pas français)","description":"Attention : VPharma est un réseau BELGE, pas un groupement français. Fondé en 1886 à Verviers sous le nom 'Pharmacies Populaires de Verviers et Arrondissement', c'est aujourd'hui un groupe coopératif de 56 pharmacies et parapharmacies (36 dans l'arrondissement Verviers-Eupen, 20 dans celui de Liège) réunissant ~450 professionnels de santé en Wallonie, province de Liège.","site":"https://www.vpharma.be/","region":"Belgique (Wallonie, province de Liège)","nbAdherents":"56 pharmacies et parapharmacies (~450 professionnels)"},"actpharmacie":{"type":"groupement / réseau de pharmaciens indépendants","description":"Réseau militant de pharmaciens indépendants créé le 11 avril 2023 par les trois co-fondateurs historiques du groupe PHR. Modèle sans droit d'entrée, très digital et orienté services, où les pharmaciens adhérents sont associés/actionnaires et participent aux commissions (achats, services). Positionné comme un réseau d'acteurs de l'évolution du métier.","site":"https://actpharmacie.fr","region":"National (siège région parisienne)","nbAdherents":"environ 87 adhérents (fin 2023 : 47 à 6 mois puis montée en charge)","dirigeants":[{"nom":"Lucien Bennatan","fn":"Co-fondateur (ex-fondateur groupe PHR)"},{"nom":"Willy Hodin","fn":"Co-fondateur / directeur"},{"nom":"Dominique Brasseur","fn":"Co-fondateur"}],"actualites":[{"titre":"Lancement officiel d'ACT Pharmacie, nouveau réseau militant fondé par les 3 co-fondateurs du groupe PHR","date":"2023-04-11","source":"Le Quotidien du Pharmacien / Le Moniteur des Pharmacies"},{"titre":"47 adhérents six mois après le lancement, une quarantaine d'autres officines en cours d'adhésion","date":"2023","source":"Le Moniteur des Pharmacies"}]},"alphegapharmacie":{"type":"enseigne / réseau de pharmaciens indépendants (adossé à un répartiteur)","description":"Réseau de pharmaciens indépendants créé et animé par Alliance Healthcare (répartiteur). Présenté comme le 1er réseau européen de pharmaciens indépendants, présent dans une dizaine de pays avec plus de 10 000 membres en Europe. Apporte aux adhérents services à forte valeur ajoutée, accompagnement commercial et marketing tout en préservant leur indépendance.","site":"https://www.alliance-healthcare.fr/alphega-pharmacie","region":"National (Europe) — Alliance Healthcare France","nbAdherents":"plus de 10 000 membres en Europe","actualites":[{"titre":"Alliance Healthcare Group France (propriétaire du réseau Alphega) annonce l'acquisition d'une participation majoritaire dans Pharmavance Groupe","date":"2025-01-06","source":"Le Moniteur des Pharmacies"}]},"axopharm":{"type":"centrale d'achat / structure de regroupement à l'achat (SRA) — PAS une enseigne grand public","description":"Structure de regroupement à l'achat pour pharmaciens associés : négociation, prises de commande et achats de produits auprès des fournisseurs pharmaceutiques pour le compte de ses adhérents. Positionnée comme un outil d'achats mutualisés plutôt que comme une enseigne de communication.","region":"France","dirigeants":[{"nom":"Michel Quaillet","fn":"Directeur général"},{"nom":"Isabelle Achon (dite Freret)","fn":"Présidente"}]},"centraledespharmaciensastera":{"type":"centrale d'achat d'un groupe coopératif","description":"Centrale d'achat du groupe coopératif Astera (1er groupe coopératif de pharmaciens en Europe, propriétaire du répartiteur CERP). Elle approvisionne environ 3 000 pharmacies avec un catalogue de plus de 5 000 références et près de 170 laboratoires partenaires (OTC, dermocosmétique, dispositifs médicaux, nutrition). Sert de centrale de référencement au réseau d'officines d'Astera.","site":"https://cdp.astera.coop","region":"National (siège du groupe Astera, Rouen/Fleury-sur-Andelle)","nbAdherents":"environ 3 000 pharmacies approvisionnées ; groupe Astera ~6 800 sociétaires","actualites":[{"titre":"Poursuite de la consolidation du pôle retail d'Astera (fusion PharmaDom, marque réseau Santalis ex-Les Pharmaciens Associés)","date":"2024","source":"Astera / Le Moniteur des Pharmacies"}]},"forumsant":{"type":"enseigne / groupement de pharmacies","description":"Enseigne de pharmacies du groupe Univers Santé (qui réunit aussi Univers Pharmacie, Escale Santé, Pharm O'Naturel, Univers Matériel Médical). Réseau d'environ 75 officines en France métropolitaine et aux Antilles-Guyane, positionné sur le conseil santé/bien-être et une offre de pharmacie à 360° avec accompagnement (référencement, merchandising, agencement, RH, formation) et outils numériques.","region":"National + Martinique, Guadeloupe, Guyane","nbAdherents":"environ 75 officines","actualites":[{"titre":"Positionnement dans l'écosystème Univers Santé aux côtés d'Univers Pharmacie","date":"2024","source":"Le Quotidien du Pharmacien"}]},"gaulixpharma":{"type":"structure de groupement à l'achat (SAS)","description":"Société (SAS créée en 2016) exerçant une activité de groupement à l'achat : approvisionnement en produits pharmaceutiques et parapharmaceutiques (usage humain et vétérinaire), OTC et marchandises pour ses adhérents. Anime le programme de fidélité pharmacie 'Antidote Pharma'.","adresse":"13 Rue de la Source du Cher, 23420 Mérinchal","region":"Creuse / Nouvelle-Aquitaine","dirigeants":[{"nom":"Christophe Benquet","fn":"Dirigeant / gérant"}]},"lecartel":{"type":"union de groupements (groupement de groupements) / centrale de négociation","description":"Premier 'groupement de groupements' français : union de quatre groupements (P&P, Pharmidée, Katalys et Orphie-lim) visant à mutualiser les achats hors grossistes et génériqueurs. Rassemble près de 300 pharmacies (CA moyen ~1,8 M€), avec des accords-cadres auprès d'une centaine de laboratoires et une cinquantaine de prestataires, pour obtenir des remises de niveau national.","region":"National","nbAdherents":"près de 300 pharmacies (4 groupements membres)","dirigeants":[{"nom":"Sébastien Rouyer","fn":"Dirigeant de l'un des groupements membres, cité pour Le Cartel"}],"actualites":[{"titre":"Création du Cartel, réunion de 4 groupements (P&P, Pharmidée, Katalys, Orphie-lim) pour peser sur les négociations","date":"2023","source":"Le Moniteur des Pharmacies / Le Quotidien du Pharmacien"}]},"maxipharma":{"type":"groupement / enseigne avec centrale d'achat interne","description":"Groupement créé par des pharmaciens pour des pharmaciens, réparti sur toute la France (environ une cinquantaine d'adhérents). Sa force est une centrale d'achat pharmaceutique interne (sans intermédiaire) optimisant les conditions d'achat, complétée d'un accompagnement personnalisé (bilan de l'officine, feuille de route, gestion, commerce).","site":"https://www.maxipharma.net","tel":"05 61 76 48 54","adresse":"14 Impasse René Couzinet, 31500 Toulouse","region":"National (siège Toulouse)","nbAdherents":"environ 50 adhérents"},"omnespharma":{"type":"groupement de pharmaciens (sans enseigne)","description":"Groupement de pharmaciens d'officine créé en 2012, sans enseigne imposée, positionné comme le 1er groupement de pharmaciens du Grand Sud-Est. Réseau de plus de 90 officines réunies autour de valeurs communes (partage, mutualisation). Anime la carte de fidélité 'My Omnes'.","site":"https://www.omnespharma.fr","adresse":"Marseille (13001)","region":"Grand Sud-Est (siège Marseille)","nbAdherents":"plus de 90 officines"},"pharmyou":{"type":"groupement de pharmacies","description":"Groupement de pharmacies créé en 2014, référençant environ 80 laboratoires pharmaceutiques. Propose adhésion annuelle, accompagnement (entretiens pharmaceutiques, formations commerciales et de gestion, démarche qualité), accords génériques et politique de prix.","site":"https://pharm-and-you.fr","email":"contact@pharm-and-you.fr","tel":"05 34 25 84 03","region":"National (indicatif tél. Sud-Ouest / Toulouse)"},"pharmagroupsantpgs":{"type":"groupement national de pharmacies indépendantes","description":"Groupement national de pharmacies indépendantes fondé en 2007 et basé à Marseille, réunissant plus de 500 adhérents. Propose une politique d'achats (centrale), des aides sell-out, de l'information quotidienne (e-catalogue) et l'accompagnement au développement économique des officines. Membre de l'UDGPO.","site":"http://www.pharmagroupsante.com","adresse":"Marseille","region":"National (siège Marseille)","nbAdherents":"plus de 500 adhérents","actualites":[{"titre":"PGS repris dans le cadre de la stratégie de croissance de Pharma Santé Développement (PSD)","date":"2017","source":"Société Générale Capital Partenaires / UDGPO"}]},"pharmacielafayette":{"type":"enseigne / groupement (discount de proximité)","description":"Grande enseigne de pharmacies à prix bas, adossée au groupe Laf Santé au sein de la holding toulousaine Hygie31. Réseau de 320 pharmacies fin 2024 pour un CA d'environ 1,22 Md€ (auxquelles s'ajoutent Optique Lafayette et Médical Lafayette). Croissance forte et continue.","adresse":"Toulouse","region":"National (siège Toulouse)","nbAdherents":"320 pharmacies (fin 2024) ; objectif 361 en 2025","actualites":[{"titre":"Plan stratégique 2025 'Gotomax' : objectif 361 pharmacies et 1,4 Md€ de CA (+15%)","date":"2025","source":"Le Moniteur des Pharmacies"},{"titre":"Hygie31 (maison mère) atteint 3,3 Md€ de CA 2024 (+22%) et intègre 244 nouveaux points de vente","date":"2024","source":"LSA Conso"}]},"pharmasant":{"type":"groupement de pharmacies","description":"Groupement de pharmacies (structure Pharmasanté Groupe) référencé parmi les partenaires des principaux éditeurs et annuaires officinaux. Informations publiques limitées ; contact via le site du groupe.","site":"https://www.pharmasante-groupe.fr","tel":"01 46 89 69 65","region":"Non confirmée avec certitude"},"quartz":{"type":"groupement de pharmaciens (au sein d'un groupe consolidateur)","description":"Groupement de pharmaciens 'par et pour les pharmaciens', voulu simple, clair et orienté résultats. Réunit environ 191 officines autour d'outils, services et partenariats définis. Fait partie du groupe Hygie31 (plus de 1 400 pharmacies, également maison mère de Pharmacie Lafayette).","site":"https://groupementquartz.fr","region":"National (groupe Hygie31, Toulouse)","nbAdherents":"environ 191 officines","actualites":[{"titre":"Quartz rattaché au groupe Hygie31 (plus de 1 400 pharmacies)","date":"2024","source":"groupementquartz.fr / PharmaPex"}]},"socopharm":{"type":"groupement régional de pharmacies (coopératif)","description":"Groupement leader à La Réunion, créé fin 2008 par plusieurs pharmaciens titulaires souhaitant mieux négocier et valoriser leurs relations fournisseurs. Réunit plus de 80 officines affiliées et sert une base d'environ 350 000 patients-clients. Combine indépendance, coopération et performance ; déploiement d'une enseigne engagé.","site":"https://socopharmreunion.com","adresse":"Saint-Denis (La Réunion)","region":"La Réunion (siège Saint-Denis)","nbAdherents":"plus de 80 officines","dirigeants":[{"nom":"Denis Ferrand","fn":"Dirigeant (cité pour le déploiement de l'enseigne)"}],"actualites":[{"titre":"Déploiement de l'enseigne Socopharm à La Réunion","date":"2019","source":"FCA Commerce associé"}]},"upie":{"type":"coopérative / union de pharmaciens (centrale de référencement)","description":"Union des Pharmaciens Indépendants Européens : société coopérative à capital variable basée à Paris. Négocie prix et contrats avec des laboratoires partenaires par segment de marché et reverse directement aux officines les RFA perçues, au prorata du CA (environ 8 000 € par million d'euros de CA). Porte aussi un concept d'officine renouvelé.","site":"https://www.upie.fr","tel":"01 53 44 70 20","adresse":"Paris","region":"National (siège Paris)"},"vitapharma":{"type":"groupement régional de pharmaciens","description":"Groupement créé en 2007 à l'initiative de pharmaciens indépendants de Martinique partageant une même vision du métier. Réunit 21 officines réparties de façon homogène sur toute l'île, positionnant les pharmaciens comme acteurs clés du système de santé local.","site":"http://www.vitapharma.fr","adresse":"Martinique","region":"Martinique","nbAdherents":"21 officines"},"agpf":{"type":"réseau / association de grandes pharmacies (membre UDGPO)","description":"L'AGPF (Association des Grandes Pharmacies de France), créée en 2001, fédère les officines à fort chiffre d'affaires (CA supérieur à 3 M€) en métropole et outre-mer. Structure sélective (une vingtaine de membres) qui mutualise le poids de négociation face aux laboratoires pour ses grandes pharmacies. Membre de l'UDGPO.","site":"http://www.agpf.fr","email":"agpfrance@wanadoo.fr","tel":"05 56 86 49 94","adresse":"38 Avenue Hubert Dubedout, 33150 Cenon","region":"National / siège Nouvelle-Aquitaine (Cenon, Gironde)","nbAdherents":"~26 membres (grandes pharmacies)","dirigeants":[{"nom":"Conseil d'administration (fondateurs : MM. Beretz, Claeys, Godfroy, Piquet, Mares, Mme Roset-Petit)","fn":"Fondateurs / gouvernance"}]},"altapharm":{"type":"groupement d'achat + SRA (structure de regroupement à l'achat)","description":"Altapharm est un groupement de pharmaciens indépendants créé en 2009 (SAS, siège à Paris 75006). Il propose une offre grossiste-répartiteur compétitive et une centrale/SRA d'environ 4 500 références OTC et parapharmacie à prix proches du direct, plus des services (merchandising, formation, communication, marques exclusives).","site":"https://altapharm.fr","region":"Hauts-de-France, Île-de-France, Normandie","nbAdherents":"Pharmaciens titulaires indépendants (non communiqué précisément)"},"bepharma":{"type":"groupement régional de pharmaciens","description":"Be Pharma est un groupement de pharmaciens fondé en 2010, ancré en Auvergne-Rhône-Alpes. Il accompagne ses adhérents et leurs équipes (agencement, management, formation) et référence des laboratoires partenaires selon des critères éthiques.","site":"https://www.bepharma.fr","region":"Auvergne-Rhône-Alpes","nbAdherents":"Réseau régional AURA (rejoint une alliance de ~300 pharmacies via Evecial)","actualites":[{"titre":"Be Pharma rejoint l'alliance Evecial, consolidant le réseau territorial (près de 300 pharmacies, ~1 Md€ de volume d'affaires)","date":"2024-2025","source":"evecial.com"}]},"copharm":{"type":"groupement coopératif de pharmaciens (filiale CERP Bretagne Atlantique)","description":"Co&Pharm (ex-Aelia) est un groupement de pharmaciens indépendants du Grand Ouest développé depuis 2009 par le répartiteur CERP Bretagne Atlantique. Il fédère plus de 700 à 800 officines de Brest à Angoulême, avec plus de 115 laboratoires partenaires, et privilégie l'indépendance sans enseigne imposée. Certifié ISO 9001:2015 (2017).","site":"https://www.coetpharm.com","region":"Grand Ouest / Arc Atlantique","nbAdherents":"~700 à 800 membres","actualites":[{"titre":"Aelia devient Co&Pharm (changement de nom du groupement CERP)","date":"vers 2023","source":"cerpba.com"}]},"epsilon":{"type":"PAS un groupement : grossiste-répartiteur indépendant + alliance/centrale d'achat (GINK'GO)","description":"Epsilon SAS n'est pas un groupement de pharmacies mais un grossiste-répartiteur pharmaceutique indépendant créé en 2015 (siège à Plan-d'Orgon, PACA). Il livre plus de 1 000 officines et a créé l'alliance GINK'GO, un modèle coopératif/centrale d'achat (extranet gink-go.fr, comparateur de remises, suivi des tensions d'appro « Météomédic ») positionné comme alternative aux grands répartiteurs.","site":"https://www.gink-go.fr","region":"Provence-Alpes-Côte d'Azur (Plan-d'Orgon, 13750)","nbAdherents":"Plus de 1 000 officines clientes"},"gpharm":{"type":"groupement régional de pharmaciens","description":"G-Pharm est un groupement fondé en 2008 à l'initiative de pharmaciens normands, visant à mutualiser pour améliorer la performance économique et l'image de ses adhérents. Identité régionale forte, proximité géographique et résultats supérieurs à la moyenne régionale mis en avant.","site":"https://g-pharm.fr","tel":"02 35 74 11 00","adresse":"2 Place de la Liberté, 76770 Le Houlme","region":"Normandie (siège au Houlme, Seine-Maritime)","nbAdherents":"Réseau régional (non communiqué)"},"gener":{"type":"centrale de référencement (rattachée au groupement Pharmacorp)","description":"Gener+ est la centrale de référencement du groupement Pharmacorp (édité par Hygie31/Lafayette Group). Pharmacorp, créé en 2012 à partir d'un noyau de pharmacies ariégeoises, se présente comme un acteur des pharmacies de proximité et fédère environ 560 pharmaciens indépendants, avec de nombreux partenariats industriels.","site":"https://hygie31.com","region":"National (origine Ariège / Occitanie, groupe Hygie31 Toulouse)","nbAdherents":"~562 pharmaciens indépendants (Pharmacorp)"},"happypharmacie":{"type":"réseau / enseigne de pharmacies (merchandising & concept)","description":"Happy Pharmacie est un réseau né en région PACA, positionné sur des officines à forte identité et merchandising, avec un accompagnement sur mesure et l'aide à l'installation de jeunes pharmaciens. Réseau encore de petite taille axé sur le bien-être du pharmacien et l'expérience client.","site":"https://www.happypharmacie.com","region":"PACA","nbAdherents":"~5 pharmacies (PACA)"},"leclubducomptoir":{"type":"groupement / club d'accompagnement (issu du Comptoir des Pharmacies)","description":"Le Club du Comptoir est un groupement créé en 2021 par Le Comptoir des Pharmacies (plateforme de déstockage, Toulouse). Il a dépassé 100 membres et se concentre sur l'optimisation des stocks et la santé financière de l'officine, via un audit data (outil Pharmed) et des solutions à la carte (merchandising, rejets de facturation, agencement, formation).","site":"https://www.leclubducomptoir.fr","region":"National (siège Toulouse)","nbAdherents":"Plus de 100 membres","actualites":[{"titre":"Le Comptoir des Pharmacies change de président (sans changement de cap)","date":"2023-2024","source":"Le Moniteur des Pharmacies"}]},"mediprix":{"type":"enseigne / marque de pharmacies (franchise + coopératives Médilab/Médiprix Corp)","description":"Médiprix est une marque santé et enseigne de pharmacies basée à Pérols (Hérault, près de Montpellier), créée en 2016. Elle revendique près de 300 pharmacies sous enseigne, ~3 000 professionnels et plus de 1,1 Md€ de CA, avec un modèle mêlant franchise 100% privée et structures coopératives. Croissance de 30 à 40 pharmacies par an.","site":"https://mediprix.fr","adresse":"Pérols (Hérault)","region":"National (siège Pérols, Occitanie) + développement Espagne","nbAdherents":"~243 à 300 pharmacies","actualites":[{"titre":"CA sous enseigne passé de 850 M€ à plus d'1 Md€ entre 2022 et 2024","date":"2024","source":"Le Journal des Entreprises"},{"titre":"Expansion en Espagne (~15 pharmacies convaincues depuis fin 2024)","date":"2024-2025","source":"Le Journal des Entreprises"},{"titre":"Entrée/soutien de l'investisseur NextStage AM pour financer la croissance et l'innovation","date":"2024","source":"NextStage AM / Le Journal des Entreprises"},{"titre":"Lancement de Pharmacology","date":"2024","source":"Le Quotidien du Pharmacien"}]},"optipharm":{"type":"groupement coopératif de pharmaciens (adhérents actionnaires)","description":"Optipharm est un groupement coopératif créé en 1988 dont tous les membres sont actionnaires, garantissant l'indépendance du pharmacien. Il revendique ~2 000 actionnaires (dont ~1 000 actifs) et dispose d'une centrale d'achat pharmaceutique (~1 600 références : génériques, OTC, princeps). Refus d'enseigne/franchise imposée, défense de la liberté d'exercice.","site":"https://optipharm.eu","region":"National","nbAdherents":"~2 000 pharmaciens actionnaires (~1 000 actifs)","actualites":[{"titre":"Optipharm réaffirme la défense de la liberté d'exercice face à la financiarisation","date":"2024-2025","source":"Le Moniteur des Pharmacies"}]},"pharmonaturel":{"type":"réseau / groupement de pharmacies « au naturel »","description":"Pharm O'naturel est le premier réseau de pharmacies au naturel en France, créé en 2010 par Sophie Brivet (pharmacienne à Vincennes) et Yves Chikli. Il fédère plus de 66-70 officines (CA moyen ~1,5 M€), réparties entre Île-de-France et province, autour d'une approche bio/naturelle (aromathérapie, phyto, diététique), plus de 90 laboratoires partenaires et un concept store à « bar à plantes ». Labellisé EnVol (éco-responsabilité).","site":"https://www.pharmonaturel.com","region":"National (Île-de-France + province)","nbAdherents":"66 à 70+ pharmacies","dirigeants":[{"nom":"Sophie Brivet","fn":"Cofondatrice"},{"nom":"Yves Chikli","fn":"Cofondateur"}],"actualites":[{"titre":"Groupement « vert » en pleine croissance, déploiement du concept store","date":"2024","source":"Le Moniteur des Pharmacies"}]},"pharmaciepopulaire":{"type":"coopérative / réseau d'officines (entité suisse — à confirmer côté France)","description":"Le nom « Pharmacie Populaire » correspond principalement à une coopérative/réseau d'officines suisse (région de Genève), active depuis 1891, positionnée sur la santé et le bien-être à prix justes. Aucun groupement français homonyme d'envergure n'a été identifié de façon fiable ; attention à l'ambiguïté si l'entité recherchée est française.","site":"https://www.pharmaciepopulaire.ch","region":"Genève / Suisse","nbAdherents":"Réseau d'officines (Suisse romande)"},"pharmastuce":{"type":"groupement / prestataire officine (peu d'informations publiques)","description":"Pharmastuce est référencée dans les annuaires de groupements de pharmacies (Labodata, Annuaire des pharmacies) et immatriculée comme société (SIREN 845 054 840), mais très peu d'informations publiques fiables sont disponibles (taille, région, dirigeants, contacts non confirmés). À vérifier directement auprès de la structure."},"resofficine":{"type":"réseau / groupement de pharmacies indépendantes","description":"Resofficine est un réseau de pharmacies indépendantes de proximité qui place le patient au cœur du développement de l'officine. Il propose des conditions négociées transparentes avec des laboratoires leaders et un panel d'une vingtaine de services à la carte (croissance, digital, fidélisation des équipes).","site":"https://www.resofficine.com","adresse":"51 bis rue d'Arsonval, 33230 Coutras","region":"National (siège Coutras, Nouvelle-Aquitaine)","nbAdherents":"Réseau national (non communiqué)"},"sofiadis":{"type":"groupement de pharmaciens (BELGE — plateforme d'achat)","description":"Sofiadis est un groupement de pharmaciens indépendants belge créé en 2009 (réseau de plus de 580 pharmacies en Belgique), adossé à un grand répartiteur (McKesson/Belmedis-Phoenix selon les sources). Il offre une plateforme d'achat optimisant approvisionnements et marge, ainsi que des services de dynamique commerciale et d'accompagnement patient. Entité belge et non française.","site":"https://www.sofiadis.be","adresse":"Rue de la Presse 4, 1000 Bruxelles (Belgique)","region":"Belgique (siège Bruxelles)","nbAdherents":"~580 pharmacies (Belgique)"},"uppultra":{"type":"offre/formule premium (« Ultra ») du groupement Pharm-UPP","description":"« UPP Ultra » désigne la formule premium d'abonnement du groupement Pharm-UPP (à côté de la formule « Essentiel » ~550 €/an). L'offre Ultra inclut quatre éléments obligatoires : carte de fidélité Privilège, offre Pharmedisound (diffusion audio en officine), fiche Google My Business et promotions commerciales (offres mensuelles + 6 promos filière/an avec affiches, via partenariat PNR Op-Pharma). Pharm-UPP, créé en 1987, est l'un des plus gros groupements de France (~1 200 pharmacies, ~2,3 Md€), 100 % détenu par des titulaires (1 membre = 1 voix).","site":"https://www.pharm-upp.fr","region":"National (environ un tiers du territoire)","nbAdherents":"~1 200 pharmacies (groupement Pharm-UPP)","dirigeants":[{"nom":"Sophie Tallaron","fn":"Présidente de Pharm-UPP"}],"actualites":[{"titre":"Nouvelle identité de marque « Pharm-UPP » pour redessiner la pharmacie indépendante","date":"2024","source":"Le Moniteur des Pharmacies"},{"titre":"Déploiement de l'espace adhérents digital (« poumon digital »)","date":"2024-2025","source":"Le Moniteur des Pharmacies"}]},"wepharma":{"type":"groupement de pharmaciens (jeune structure)","description":"We Pharma est un groupement né de la vision de quatre pharmaciens amis autour de valeurs d'entraide, de confiance et d'excellence. Basé à Vitry-sur-Seine (94), il vise le bien-être patient et la performance commerciale de ses adhérents via accompagnement continu, partenariats exclusifs et ressources dédiées. Structure récente (site en refonte en 2026).","site":"https://we-pharma.com","adresse":"Vitry-sur-Seine (94400)","region":"National (siège Vitry-sur-Seine, Val-de-Marne)","nbAdherents":"Jeune réseau (non communiqué)"},"apis":{"type":"inconnu / non identifié","description":"Aucune information fiable trouvée. Aucun groupement de pharmacies nommé « APIS » n'apparaît dans les annuaires professionnels (labodata lettre A, choisirmongroupement, annuaire des-pharmacies), ni parmi les membres de la fédération APSAGIR. Nom possiblement erroné, très local, ou confusion avec un autre sigle (ex. Aptiphar, Apsara, Aprium). À reconfirmer avec plus de contexte."},"altipharma":{"type":"groupement d'achat (SAS à capital variable)","description":"Petite centrale d'achat de pharmaciens indépendants (~18 pharmaciens/officines) implantée en Haute-Loire (Auvergne). Elle centralise les commandes et négocie avec les fournisseurs (matériel médical, dispositifs médicaux, médicaments non remboursables, parapharmacie) pour renforcer la compétitivité de ses adhérents. Structure régionale de proximité, pas une enseigne nationale.","adresse":"Chadrac (43770) — siège transféré de Vorey-sur-Arzon en octobre 2021","region":"Auvergne-Rhône-Alpes (Haute-Loire, 43)","nbAdherents":"~18 pharmaciens","actualites":[{"titre":"Transfert du siège social de Vorey-sur-Arzon vers Chadrac (43770)","date":"octobre 2021","source":"Pappers (SIREN 831931860)"}]},"boticinal":{"type":"enseigne / groupement de très grandes pharmacies","description":"Enseigne et groupement fondé en 2016 par François et Florence Rochet, positionné sur les très grandes pharmacies et l'e-commerce. Réseau national (France et Espagne, ex. Paris, Marseille, Lyon, Avignon, Barcelone) qui s'appuie sur deux vaisseaux amiraux : la Pharmacie du RER (parmi les plus grandes de France) et boticinal.com, classé parmi les tout premiers sites de parapharmacie en ligne. Concept moderne, identité rouge/vert.","site":"https://www.group.boticinal.com","region":"National (France + Espagne), siège en Île-de-France","dirigeants":[{"nom":"François Rochet","fn":"cofondateur"},{"nom":"Florence Rochet","fn":"cofondatrice"}],"actualites":[{"titre":"Lancement d'« Officinal by Boticinal », concept dérivé destiné aux pharmacies de proximité (santé naturelle, dynamique commerciale)","date":"2024","source":"Le Moniteur des Pharmacies / group.boticinal.com"}]},"cofisant":{"type":"société de services / groupement de pharmaciens indépendants","description":"Groupement créé en 1995, positionné comme société de services (et non simple centrale d'achat) au service de la rentabilité de ses membres. Fédère un peu plus de 150 pharmacies (CA moyen ~2 M€) réparties dans près de 70 départements. Revendique une croissance supérieure de ~5 % au marché : référencement produits/labos, formation, accompagnement des équipes et communication sous bannière commune tout en respectant l'identité de chacun.","site":"https://www.cofisante.net","region":"National (~70 départements)","nbAdherents":"~150 pharmacies"},"escalesant":{"type":"groupement de pharmaciens indépendants (réseau régional)","description":"Groupement de pharmaciens indépendants créé en 2007, ancré en Île-de-France, réunissant environ 120-125 officines (CA moyen ~1,8 M€). Services « à la carte » et sans contrainte : choix d'enseigne, agencement, offres promo, outils d'aide à la vente, plateforme d'achat 24/7. Cible les indépendants, GIE et groupements informels souhaitant garder leur autonomie.","site":"https://groupe.escale-sante.net","adresse":"Paris 15e","region":"Île-de-France","nbAdherents":"~120-125 officines","actualites":[{"titre":"Rachat / intégration par Univers Pharmacie (galaxie Hygie31), avec Pharm O'Naturel — Escale Santé rejoint le giron d'Univers Pharmacie","date":"septembre 2023","source":"Le Moniteur des Pharmacies / Le Quotidien du Pharmacien"}]},"g1000pharmacies":{"type":"groupement / centrale d'achat de pharmaciens indépendants","description":"Groupement (G1000 Pharma) créé en 2011 à l'initiative de deux pharmaciens, basé à Marseille, avec pour objectif de rationaliser et optimiser les conditions d'achat de ses membres. Réseau important revendiquant environ 1 250 pharmacies et 1 700 pharmaciens. Il fait partie du groupe PSD, qui réunit trois groupements : Pharma Group Santé, G1000 Pharma et Népenthès.","region":"National, siège à Marseille (PACA)","nbAdherents":"~1 250 pharmacies / ~1 700 pharmaciens","actualites":[{"titre":"Intégration au sein du groupe PSD (Pharma Group Santé + G1000 Pharma + Népenthès)","source":"choisirmongroupement.com / Le Moniteur des Pharmacies"}]},"giphar":{"type":"coopérative de pharmaciens indépendants","description":"L'un des principaux groupements français : coopérative exclusive de pharmaciens indépendants regroupant environ 1 250 officines, dont tous les bénéfices sont redistribués aux adhérents. Siège à Roubaix (Hauts-de-France). Offre référencement, marque enseigne, services patients, formation et outils digitaux.","region":"National, siège à Roubaix (Hauts-de-France)","nbAdherents":"~1 250 officines","dirigeants":[{"nom":"Benoît Le Gavrian","fn":"Président du directoire (depuis 2022)"},{"nom":"Magali Ghirardi","fn":"Directrice générale du directoire"},{"nom":"Pierre-Xavier Frank","fn":"Directeur général / pharmacien responsable"},{"nom":"Valérie Kieffer","fn":"Présidente nationale"}],"actualites":[{"titre":"Giphar devient membre fondateur du collège pharmacie de la FCA (Fédération du Commerce Coopératif et Associé)","date":"novembre 2024","source":"Le Quotidien du Pharmacien / FCA"},{"titre":"Nouveau président du directoire (Benoît Le Gavrian)","date":"2022","source":"Le Moniteur des Pharmacies"}]},"hellopharmacie":{"type":"groupement coopératif de pharmaciens indépendants","description":"Groupement coopératif et égalitaire créé en 2008, certifié ISO 9001, implanté en Auvergne-Rhône-Alpes, réunissant une centaine d'officines (~103). Signature « On s'occupe de vous », valeurs de bienveillance et de confiance, 100 % des résultats redistribués aux membres. Achats négociés avec 80+ laboratoires, outils statistiques/qualité, formation, trade marketing, enseigne commune.","region":"Auvergne-Rhône-Alpes","nbAdherents":"~103 pharmacies","dirigeants":[{"nom":"Marc Mougenot","fn":"dirigeant / porte-parole (interviews)"}],"actualites":[{"titre":"Lancement d'un nouveau concept store Hello Pharmacie","source":"Le Quotidien du Pharmacien"}]},"legallsantservices":{"type":"réseau / groupement d'officines (devenu Essentiels Pharma)","description":"Réseau d'officines sous bannière commune fondé par Christophe Le Gall (fin des années 1990 / 2007), désormais opérant sous le nom Essentiels Pharma. Petit réseau (~15 pharmacies) dans l'Ouest (siège à Beaucouzé/Angers, Maine-et-Loire, Pays de la Loire). Internalise la gestion du back-office des officines. Centrale d'achat donnant accès à 225+ laboratoires et 10 000+ références.","site":"https://essentiels-pharma.fr","adresse":"Beaucouzé / Angers (49)","region":"Pays de la Loire (Maine-et-Loire), Grand Ouest","nbAdherents":"~15 officines","dirigeants":[{"nom":"Christophe Le Gall","fn":"fondateur"}],"actualites":[{"titre":"Le Gall Santé Services partage sa centrale d'achat avec Univers Pharmacie","date":"juin 2019","source":"Le Moniteur des Pharmacies"},{"titre":"Évolution de la marque vers « Essentiels Pharma »","source":"legall-sante.com / LinkedIn"}]},"medisavoie":{"type":"inconnu / non identifié","description":"Aucune information fiable trouvée. Aucun groupement « Medisavoie » / « Médisavoie » ne figure dans les annuaires professionnels (labodata lettre M — n'y figurent que Magdaleon, Mediprix, Multipharma, Mutualpharm —, choisirmongroupement, annuaire des-pharmacies) ni dans la presse pro. Possiblement une petite structure locale de Savoie non référencée, un nom erroné, ou une confusion. À reconfirmer avec plus de contexte."},"originsant":{"type":"groupement de pharmaciens indépendants (centrale d'achat + merchandising)","description":"Groupement créé en 2013 par des pharmaciens indépendants, basé à Strasbourg (Grand Est). Optimise les achats, dynamise le point de vente et améliore les marges tout en laissant aux officines leur autonomie de négociation et de gestion. Propose conditions d'achat préférentielles, animation, merchandising et plateformes web (OriginSanté 2.0). CA rapporté ~46,8 M€.","site":"http://www.originsante.fr","tel":"03 88 50 66 43","adresse":"7 rue Schott, 67000 Strasbourg","region":"Grand Est (Alsace), siège Strasbourg"},"pharmfree":{"type":"groupement régional (SRA) — membre de la fédération APSAGIR","description":"Groupement régional au service de l'indépendance du pharmacien, historiquement implanté dans la Marne, l'Aisne et les Ardennes (Grand Est / Hauts-de-France). Plus de 60 membres et 70+ laboratoires référencés. Membre actif de la fédération APSAGIR (800-1000+ pharmacies), avec laquelle il mutualise services et pouvoir de négociation. Centrale de 14 000+ références commandables.","site":"https://www.pharmnfree.fr","email":"info@pharmnfree.fr","tel":"03 26 04 64 55","region":"Marne, Aisne, Ardennes (Grand Est / Hauts-de-France)","nbAdherents":"60+ membres","actualites":[{"titre":"Membre de la fédération APSAGIR (14 groupements régionaux, 1000+ pharmacies indépendantes)","source":"apsagir.fr / pharmnfree.fr"}]},"pharmaprovence":{"type":"réseau / groupement régional de pharmacies","description":"Réseau de pharmacies de la région PACA, né de l'initiative de trois amis pharmaciens autour de la mutualisation et de l'optimisation des négociations commerciales. Historiquement implanté dans les Bouches-du-Rhône et le Var, il s'étend à toute la région Provence-Alpes-Côte d'Azur. Communication et offres commerciales communes façon chaîne de proximité ; valeurs d'écoute, respect, partage, transparence.","site":"https://pharmaprovencegroupe.com","tel":"04 94 35 91 01","adresse":"145 chemin du Palyvestre, « L'abattoir » lieu-dit, 83400 Hyères","region":"Provence-Alpes-Côte d'Azur (Bouches-du-Rhône, Var)"},"pharmaciescos":{"type":"coopérative de pharmaciens indépendants","description":"Coopérative fédérant plus de 350 pharmacies indépendantes réparties sur tout le territoire national, réunies autour de valeurs partagées (proximité, équité, performance, indépendance, transparence, engagement). Améliore la performance commerciale, apporte services à valeur ajoutée et accompagnement opérationnel, et prépare les officines aux transformations du métier. Siège à Paris.","site":"https://pharmaciecos.fr","adresse":"26 rue du Faubourg Saint-Antoine, 75012 Paris","region":"National, siège à Paris","nbAdherents":"350+ pharmacies","actualites":[{"titre":"COS Pharmacie rejoint la FCA (Fédération du Commerce Coopératif et Associé), aux côtés de Notaires Office","source":"commerce-associe.fr (FCA)"}]},"pharmasud":{"type":"groupement régional de pharmaciens (coopératif) — membre fédération APSARA","description":"Groupement régional « au service de l'indépendance du pharmacien » depuis 1986, réunissant environ 75-80 officines réparties sur 4 départements : Aude, Gard, Hérault et Pyrénées-Orientales (Occitanie). Valeurs de solidarité, transparence et collégialité. Dispose d'une plateforme d'achat sur deux sites (Narbonne et Montpellier Saint-Aunès) et d'une société de matériel médical (Pharmasud Medical). Membre de la fédération APSARA (750+ pharmacies). Enseigne commune (logo zèbre) depuis 2018.","site":"https://www.pharmasud.fr","region":"Occitanie (Aude, Gard, Hérault, Pyrénées-Orientales)","nbAdherents":"~75-80 officines","actualites":[{"titre":"Extension de la plateforme d'achat à Narbonne et Montpellier","source":"Le Quotidien du Pharmacien"}]},"rseaupp":{"type":"réseau / groupement de pharmacies de proximité","description":"Réseau créé en 2016, dédié aux petites et moyennes pharmacies de proximité, comptant plus de 100 officines en France. Se distingue par un « Majordome » (concierge dédié) qui accompagne l'officine au quotidien comme un membre d'équipe supplémentaire. Propose la P&P Academy (formation), une carte de fidélité inter-officines, un service flash & collect, et est à l'origine du label « Ma Pharmacie de Famille ».","site":"https://reseau-pnp.com","region":"National","nbAdherents":"100+ pharmacies","actualites":[{"titre":"Création et déploiement du label « Ma Pharmacie de Famille »","source":"reseau-pnp.com / Revue Pharma"}]},"solipharm":{"type":"groupement / réseau de pharmaciens indépendants (membre alliance Evecial)","description":"Groupement de pharmaciens indépendants basé dans le Nord-Ouest (Bretagne, Pays de la Loire, Normandie). Particularité : réseau non dirigé par un pharmacien mais par un profil issu du commerce/marketing pharmaceutique, apportant un regard externe. Approche personnalisée et offres « à la carte » : audits d'officine, outils de gestion, large choix de partenaires, formation, télémédecine, merchandising.","site":"https://www.solipharm.fr","region":"Grand Ouest (Bretagne, Pays de la Loire, Normandie)","actualites":[{"titre":"Solipharm rejoint l'alliance de groupements Evecial (400+ pharmacies)","date":"fin 2024 (septembre 2024)","source":"Evecial / Le Moniteur des Pharmacies"}]},"uniq":{"type":"réseau / enseigne (pôle Retail de la coopérative Astera)","description":"Réseau lancé en janvier 2024 par Astera (coopérative CERP Rouen), dédié aux grandes pharmacies réalisant plus de 4 M€ de CA annuel et situées en environnement fortement concurrentiel. Il complète le pôle Retail d'Astera aux côtés des réseaux Santalis et Paraph, dans une stratégie de montée en gamme et de différenciation selon les typologies d'officines.","region":"National (coopérative Astera, siège Rouen)","dirigeants":[{"nom":"Groupe Astera (coopérative CERP Rouen)","fn":"structure de rattachement"}],"actualites":[{"titre":"Lancement du réseau UniQ pour les pharmacies de plus de 4 M€ de CA","date":"janvier 2024","source":"Le Quotidien du Pharmacien / Astera"},{"titre":"Astera renforce son pôle Retail (acquisition Paraph août 2023, Pharmadom juin 2024)","date":"2023-2024","source":"FCA / Astera"}]},"wellpharma":{"type":"groupement national de pharmaciens (coopérative Welcoop)","description":"Groupement national (ex-Objectif Pharma) rattaché à La Coopérative Welcoop, détenue à 100 % par des pharmaciens. Réunit plus de 450 officines et génère ~900 M€ de CA/an. S'appuie sur une force d'animateurs réseau de proximité et sur l'outil exclusif Sloop Data (pilotage en temps réel des remises et conditions commerciales grossistes/génériqueurs/laboratoires) pour optimiser la rentabilité et préserver l'indépendance des adhérents.","site":"https://wellpharma.com","region":"National, coopérative basée à Villers-lès-Nancy (Nancy, Grand Est)","nbAdherents":"450+ officines","dirigeants":[{"nom":"Thierry Chapusot","fn":"Président du conseil de surveillance de Wellpharma"},{"nom":"Jean-Pierre Dosdat","fn":"membre du directoire de La Coopérative Welcoop (ex-président du conseil de surveillance de Wellpharma 2011-2022)"}],"actualites":[{"titre":"Déploiement de l'outil Sloop Data (pilotage temps réel des conditions commerciales)","source":"wellpharma.com / La Coopérative Welcoop"}]},"apm":{"type":"coopérative","description":"APM = Coopérative « Les Pharmaciens de Méditerranée ». Coopérative de pharmaciens indépendants créée en 1995 (association) puis transformée en coopérative en 2009, présentée comme la 1re coopérative de pharmaciens indépendants du sud de la France. Plus de 90 adhérents ; mutualisation des achats et négociation de contrats commerciaux avec des laboratoires partenaires tout en préservant l'indépendance des titulaires. À NE PAS confondre avec Coop APM Provence (APM 84).","site":"https://www.lespharmaciensdemediterranee.com","adresse":"1415 Avenue Albert Einstein, 34000 Montpellier","region":"Occitanie / sud de la France (base Montpellier)","nbAdherents":"90+ officines","dirigeants":[{"nom":"Conseil d'administration de 12 membres bénévoles","fn":"Gouvernance (pharmaciens associés)"}]},"antonwillem":{"type":"enseigne / réseau (filiale coopérative Welcoop)","description":"Réseau/enseigne de pharmacies spécialisées « santé au naturel » (phytothérapie, aromathérapie, micronutrition) créé en 2014, adossé à La Coopérative Welcoop. Modèle d'exclusivité territoriale par pharmacie, positionnement naturel/alternatif en complément du médicament classique. Réseau en forte croissance dépassant 70 pharmacies en France.","site":"https://anton-et-willem.fr (recrutement : rejoindreantonetwillem.fr)","region":"National (France)","nbAdherents":"70+ pharmacies","actualites":[{"titre":"Poursuite du développement du réseau : ~70 pharmacies visées, 9 ouvertures en 2023 puis 6 nouvelles officines au 2e semestre 2024","date":"2023-2024","source":"Le Moniteur des Pharmacies / rejoindreantonetwillem.fr"}]},"bretagnepharma":{"type":"enseigne régionale (au sein du Groupe OPSO Santé)","description":"Enseigne régionale de pharmacies réunie, avec Normandie Pharma et OPSO Pharma, sous l'identité B2B commune Groupe OPSO Santé. Chaque marque conserve son enseigne côté patients mais la gestion (achats, négociation) est centralisée sous OPSO Santé. Le groupe compte environ 125 pharmacies (contre 87 deux ans plus tôt), historiquement ancré en Bretagne et Normandie et en extension vers les régions limitrophes.","site":"https://www.bretagnepharma.fr (groupe : opsosante.fr)","region":"Bretagne / Normandie et régions limitrophes","nbAdherents":"≈125 officines (ensemble Groupe OPSO Santé)","dirigeants":[{"nom":"Frédéric Legendre","fn":"dirigeant Normandie Pharma / Groupe OPSO Santé"}],"actualites":[{"titre":"Consolidation de l'identité : Normandie Pharma, Bretagne Pharma et OPSO Pharma réunis sous une même identité B2B (Groupe OPSO Santé) ; extension du territoire (Eure-et-Loir, Sarthe...)","date":"2024-2025","source":"Le Moniteur des Pharmacies"}]},"coopapmprovenceapm84":{"type":"coopérative / centrale d'achat (SRA)","description":"Coopérative d'achat de pharmaciens (Coopérative d'Achats des Pharmaciens de Provence) créée en 2014, pilotée 100% par les pharmaciens titulaires. Relations privilégiées avec CERP RRM et accès à la centrale COALIA (mutualisation d'achats de près de 1 600 officines avec Pharm UPP et APP Sud). Cotisation 590€/an en 2025 + 80 parts sociales à 10€.","site":"https://www.coopapm84.fr","adresse":"10 Avenue de Fontcouverte, 84000 Avignon","region":"Provence / Vaucluse (84)","nbAdherents":"réseau local Provence (via COALIA ≈1 600 officines mutualisées)","actualites":[{"titre":"Création avec CERP RRM et les groupements Pharm UPP et APP Sud de la centrale COALIA pour mutualiser les achats de près de 1 600 officines","date":"","source":"lespharmaciensdemediterranee.com / coopapm84.fr"}]},"essentielspharma":{"type":"réseau d'enseignes fédérées + centrale d'achat","description":"Anciennement Le Gall Santé Services (créé en 1997). Regroupe un réseau d'enseignes de pharmacies fédérées (niveaux Prestige, Premium, Premium+, Optimum), un réseau de pharmacies indépendantes groupées sans enseigne (offre « Discovery », sans engagement) et une centrale d'achat. La centrale sert environ 507 clients avec 12 500 références ; ~23 pharmacies sous enseigne + 20 pharmacies Essentiels Pharma. Distribution en flux tirés et services à forte valeur ajoutée.","site":"https://essentiels-pharma.fr","region":"National (base Grand Ouest)","nbAdherents":"~43 officines enseigne + centrale ~507 clients","dirigeants":[{"nom":"François Tesson","fn":"Président"}]},"gam":{"type":"GIE (groupement d'achats mutualiste)","description":"GAM = Groupement d'Achats Mutualiste. GIE à but non lucratif créé en 2012 à l'initiative d'organismes mutualistes (GHMF, Générations Mutualistes) pour mutualiser les achats d'établissements de santé, médico-sociaux, petite enfance et pharmacies mutualistes. Négocie achats de produits médicaux et non médicaux, prestations, consommables et équipements. Initialement réservé aux structures mutualistes puis ouvert à d'autres acteurs.","site":"https://gam-mut.fr","region":"National (France)","nbAdherents":"32 pharmacies mutualistes (volet officine)","actualites":[{"titre":"Les 32 pharmacies mutualistes du GAM rejoignent Pharmacorp (écosystème Hygie31) à compter du 1er janvier 2026","date":"2026-01-01","source":"Hygie31 / Le Moniteur des Pharmacies"}]},"giropharm":{"type":"coopérative / enseigne","description":"Coopérative de pharmaciens indépendants créée en 1986, l'une des grandes coopératives nationales sous enseigne. Les pharmaciens sont associés et actionnaires. Environ 530 officines (679 pharmaciens) et 102 laboratoires référencés avant le rapprochement avec Apothera. Objectif : faciliter la gestion quotidienne et développer la rentabilité des officines.","site":"https://www.giropharm.fr","tel":"01 49 79 98 58","adresse":"19 rue d'Arcueil, Immeuble Québec, CS 80073, 94528 Rungis Cedex","region":"National (siège Rungis)","nbAdherents":"≈530 officines (≈1 800 avec Apothera)","dirigeants":[{"nom":"Luc Priouzeau","fn":"Président-Directeur Général"},{"nom":"Gilles Unglik","fn":"Directeur Général"}],"actualites":[{"titre":"Acquisition d'Apothera : Giropharm devient le 1er groupe coopératif de pharmacies en France (~1 800 pharmacies partenaires, ~13 000 collaborateurs, 4 Mds€ de CA, 9,2% du marché officinal). Intégration de la centrale d'achat et accès à NEP La Marque et Pharmacarde dès le T1 2025","date":"2024-2025","source":"Le Moniteur des Pharmacies / Le Quotidien du Pharmacien / L'Express Franchise"}]},"hexapharm":{"type":"groupement (réseau à taille humaine)","description":"Groupement de pharmacies « à taille humaine » axé sur la synergie de compétences (réflexion, actualisation, optimisation), respectant l'autonomie et l'indépendance de chaque titulaire. 85 adhérents et 126 laboratoires référencés. Services : visites régulières d'un référent, réponses personnalisées, 2 séminaires par an.","site":"http://www.hexapharm.fr","email":"contact@hexapharm.fr","tel":"03 90 20 33 35","region":"Grand Est (Alsace) / national","nbAdherents":"85 adhérents","dirigeants":[{"nom":"Stanis Ekman","fn":"Président"}]},"leadersant":{"type":"groupement de pharmacies indépendantes","description":"Réseau de pharmacies indépendantes regroupant plus de 600 officines affiliées autour de valeurs de partage et de respect. Fondé par trois jeunes pharmaciens titulaires (Samuel, Antoine et Alexis Berreby). Accompagnement à l'installation, trade marketing et digitalisation.","site":"https://www.leadersante-groupe.fr","region":"National (France)","nbAdherents":"600+ officines","dirigeants":[{"nom":"Alexis Berreby","fn":"Co-fondateur"},{"nom":"Samuel et Antoine","fn":"Co-fondateurs"}],"actualites":[{"titre":"Rapprochement des 25 officines Côté Pharma avec le groupement Leader Santé","date":"2024-2025","source":"Le Moniteur des Pharmacies"}]},"multipharma":{"type":"coopérative (belge)","description":"ATTENTION : le seul « Multipharma » fiablement identifié est la coopérative belge (Bruxelles), plus de 100 ans d'existence, réseau de ~273 à 320 pharmacies et ~1 700 collaborateurs, modèle coopératif centré sur l'accessibilité des soins et le réinvestissement des bénéfices. Aucun groupement FRANÇAIS distinct sous ce nom exact n'a été trouvé — à vérifier côté CRM (possible confusion ou petite structure locale).","site":"https://www.multipharma.be","adresse":"Square Marie Curie 30, 1070 Bruxelles (Belgique)","region":"Belgique (Bruxelles) — pas France","nbAdherents":"≈273-320 pharmacies (réseau belge)"},"orphie":{"type":"coopérative de pharmaciens","description":"Coopérative de pharmaciens créée en 2002, environ 60 adhérents, principalement dans le Sud-Loire, la Vendée et le Poitou-Charentes. Dirigée par des pharmaciens (une seule salariée, coûts réduits), sans droit d'entrée ni cotisation, avec transparence des comptes et redistribution intégrale des bénéfices. Entités liées : Orphie Lim (2010) et Orphie Provence (2011, ~17 officines en Provence).","site":"https://www.orphie-groupement.com","region":"Sud-Loire / Vendée / Poitou-Charentes","nbAdherents":"≈60 adhérents"},"pharmauvergne":{"type":"groupement + centrale d'achat","description":"Groupement de pharmaciens fondé en 2018 par Sébastien Manlhiot, basé en Auvergne (région clermontoise), environ 70 officines. Positionné sur l'indépendance : audit grossiste et génériques, études géomarketing, veille concurrentielle et centrale d'achat avec partenariats laboratoires négociés.","site":"https://www.pharm-auvergne.com","tel":"06 82 98 77 43","adresse":"3 Rte de St Babel (Naves), 63500 Orbeil","region":"Auvergne (Puy-de-Dôme)","nbAdherents":"≈70 officines","dirigeants":[{"nom":"Sébastien Manlhiot","fn":"Fondateur"}],"actualites":[{"titre":"Intégration à l'écosystème Hygie31 : accès à HygieStore (plateforme d'approvisionnement, +25 000 produits)","date":"2024-2025","source":"Hygie31"}]},"pharmastar":{"type":"petit groupement régional","description":"Petit groupement de pharmaciens du Sud-Ouest (Dordogne, Lot-et-Garonne, Charente-Maritime), né avec une poignée d'officines (de 4 à 8), créé pour obtenir de bonnes conditions commerciales tout en préservant l'indépendance vis-à-vis des grands groupements financiarisés. Partenaires historiques : distributeur Alliance Healthcare et génériqueur Arrow. Membre de la fédération APSAGIR (14 groupements, +1 000 officines) défendant l'officine indépendante.","site":"https://pharmastar.fr","region":"Sud-Ouest (Dordogne, Lot-et-Garonne, Charente-Maritime)","nbAdherents":"≈8 officines"},"pharmacodynamique":{"description":"Aucune information fiable trouvée sur un groupement de pharmacies nommé « Pharmacodynamique » (absent des annuaires LaboData, choisirmongroupement, presse pro). Le terme renvoie uniquement à la notion pharmacologique. À vérifier / préciser l'orthographe ou la région côté CRM."},"pharmatir":{"description":"Aucune information fiable trouvée sur un groupement/SRA nommé « Pharmatir » (absent des annuaires LaboData, choisirmongroupement et de la presse pro). Structure possiblement très locale, récente ou disparue, ou orthographe différente. À vérifier côté CRM."},"rseaupharma":{"type":"réseau de pharmaciens indépendants","description":"Correspondance la plus probable : Réseau Pharma Méditerranée (RPM). Réseau de pharmaciens indépendants en PACA et Corse, positionné « soutien sans contraintes » (l'officine garde son autonomie). Trois piliers : optimisation des achats (105 accords laboratoires), outils de gestion (tableau de bord Smart 360, académie de +200 modules) et développement digital (site, appli, fidélité). Abonnement 39€ HT/mois tout compris. NB : le nom exact « Réseau Pharma » est ambigu — à confirmer qu'il s'agit bien de RPM côté CRM.","site":"https://groupement-rpm.fr","email":"contact@groupement-rpm.fr","tel":"06 26 24 85 80","adresse":"Allée de la Rouguière, 13011 Marseille","region":"PACA et Corse (base Marseille)","nbAdherents":"40+ pharmacies partenaires (fournisseurs affichés)","dirigeants":[{"nom":"Dr Eric Mollard","fn":"Directeur Général (ancien pharmacien titulaire)"}]},"sopharef":{"type":"groupement + société de référencement (centrale d'achat)","description":"Sopharef (Société Pharmaceutique de Référencement), à la fois groupement de pharmaciens et centrale de référencement, créée en juillet 2008. Objectif : mutualiser les forces pour de meilleures conditions d'achat, sans droit d'entrée. Environ 17 adhérents. Plateforme sopharef.com : 250 laboratoires et 18 000 références, 99% des produits commandables à l'unité avec livraisons quotidiennes.","site":"https://groupementsopharef.com","adresse":"52 rue de Kerbellec, 56610 Arradon","region":"Bretagne (Morbihan)","nbAdherents":"≈17 adhérents"},"uniondesgrandespharmaciesugp":{"type":"association loi 1901","description":"Association loi 1901 créée en 1996 réunissant de grandes pharmacies, des laboratoires et des personnalités du monde pharmaceutique, avec 107 laboratoires référencés. Objectifs : organe de concertation, amélioration de l'image de la pharmacie, formation professionnelle, défense du commerce traditionnel. Services : accords multi-génériques, aide à la politique de prix, formation, congrès, enseigne, géomarketing, merchandising, opérations commerciales, marques de distributeur (générique et parapharmacie).","adresse":"Résidence Le Garage, 7 A bis rue Bras de Fer, 76000 Rouen","region":"National (siège Rouen, Normandie)","nbAdherents":"grandes pharmacies ; 107 labos référencés","dirigeants":[{"nom":"Yves Rivière","fn":"Président"},{"nom":"Paul Vincente","fn":"Vice-Président"}]},"ipharm":{"type":"groupement de pharmaciens indépendants","description":"Réseau de pharmacies créé en 2009 en Île-de-France par des pharmaciens titulaires, autour de 4 valeurs : convivialité, transparence, pragmatisme, innovation. Environ 64 adhérents (2023), présent en Île-de-France et dans le Sud-Ouest, en ouverture vers de nouvelles régions. Se positionne comme proche de ses adhérents, mise sur Paris et les jeunes installés ; services d'accompagnement à l'installation, trade marketing et digitalisation.","site":"https://www.ipharm.fr","tel":"02 31 64 10 95","region":"Île-de-France + Sud-Ouest","nbAdherents":"≈64 adhérents (2023)","actualites":[{"titre":"Objectif d'expansion du réseau de +28%, priorité à Paris et aux jeunes pharmaciens","date":"2023","source":"Le Quotidien du Pharmacien"}]},"apm34lespharmaciensdemditerranemontpellier":{"type":"coopérative / groupement","description":"Coopérative de pharmaciens créée en 1995 (APM = Association/Coopérative des Pharmaciens de Méditerranée). Réseau indépendant « des pharmaciens au service des pharmaciens » qui regroupe environ 220 officines, soit près de la moitié des pharmacies de l'Hérault. Apporte la négociation de conditions commerciales (labos partenaires, grossistes, centrale APM), des solutions logistiques et un accompagnement performance/rentabilité.","site":"https://www.lespharmaciensdemediterranee.com","tel":"06 25 89 73 09","adresse":"1415 Avenue Albert Einstein, 34000 Montpellier","region":"Occitanie (Hérault / pourtour méditerranéen)","nbAdherents":"~220 officines","actualites":[{"titre":"Fête ses ~29 ans d'existence, positionnement coopératif réaffirmé (des pharmaciens au service des pharmaciens)","date":"2024","source":"lespharmaciensdemediterranee.com"}]},"apofficine":{"type":"groupement (actionnariat pharmacien)","description":"Groupement de pharmacies au modèle actionnarial : chaque pharmacien devient actionnaire et décideur. Cotisation annoncée à 0 €. Basé dans la Drôme, il optimise les achats (centrales de référencement, génériqueurs, grossistes) et propose dynamisation commerciale, agencement, solutions numériques, marketing et formations. Développe aussi un « Hub Services de Solutions Santé » (Meta Pharm Invest, pharmacie 4.0).","site":"http://www.apofficine.fr","tel":"06 22 34 42 54","adresse":"25 rue Albert Camus, 26800 Portes-lès-Valence","region":"Auvergne-Rhône-Alpes (Drôme)"},"bretagnesantrfrence":{"type":"groupement régional","description":"Groupement régional breton (BSR) créé en 2010, comptant environ 27 pharmacies réparties sur le Finistère, les Côtes-d'Armor et l'Ille-et-Vilaine. Particularité : toutes les officines partagent le même grossiste et le même distributeur de génériques, et l'ensemble du groupement est engagé dans une démarche qualité certifiée — l'un des rares groupements entièrement certifiés en France. Se veut plus qu'une centrale d'achat : conseil, accompagnement et sens donné à l'activité.","site":"https://www.pharmacies-bsr.fr (aussi bsr.bzh)","adresse":"1 Rue du Docteur Gringoire, 35120 Dol-de-Bretagne","region":"Bretagne","nbAdherents":"~27 pharmacies"},"ddocteursenpharmacieetphd":{"type":"néogroupement / enseigne","description":"PHD se présente comme le « premier néogroupement » : écosystème agile, transparent et très digitalisé au service des pharmaciens indépendants, articulé autour de plusieurs marques. « D Docteurs en Pharmacie » est l'une de ses enseignes premium : premier concept santé multi-spécialiste, orienté services et humanité, avec un programme MOVE by D pour accompagner les primo-installants. La force du réseau : l'indépendance du pharmacien et une équipe d'experts de terrain.","site":"https://phd-pharmacies.com","region":"France (national)","actualites":[{"titre":"PHD structure son réseau autour de plusieurs enseignes dont D Docteurs, positionnées par niveau d'ambition","date":"2024","source":"phd-pharmacies.com"}]},"gfcpharmacooprative":{"type":"coopérative","description":"GFC = Groupement Franco-Cambodgien des Pharmaciens. Coopérative née vers 2010 de la volonté de pharmaciens titulaires d'origine cambodgienne de créer « un groupement qui compte », basée à Torcy (Seine-et-Marne). Elle fait partie des coopératives de pharmaciens membres du collège pharmacie de la FCA (Fédération du Commerce Associé), aux côtés de Giphar, Astera, Giropharm, Welcoop, Totum, Elsie Santé, Socopharm et Cos Pharmacie.","site":"https://gfc.pharminfo.fr","adresse":"Torcy (77), Seine-et-Marne — SIREN 523319028","region":"Île-de-France (Torcy 77) — national","actualites":[{"titre":"Cité parmi les groupements/coopératives s'associant pour préserver l'indépendance face à la financiarisation","date":"2024-2025","source":"Le Moniteur des Pharmacies"}]},"globalpharmacie":{"type":"groupement","description":"Groupement créé en 2009, positionné spécifiquement sur les petites et moyennes officines (notamment de moins de 50 m² de surface de vente), un segment souvent délaissé. Basé à Colmar, il affine sa stratégie commerciale pour apporter des solutions adaptées aux pharmacies de proximité, avec des valeurs tournées vers l'avenir, le progrès et la modernité.","site":"http://www.globalpharmacie.fr","tel":"03 89 41 68 45","adresse":"97 Route de Neuf-Brisach, 68000 Colmar","region":"Grand Est (Colmar 68) — national"},"hygie31":{"type":"holding / groupe d'enseignes (PAS un groupement classique)","description":"PAS un groupement coopératif : Hygie31 est une holding d'origine toulousaine qui pilote plusieurs enseignes majeures (Pharmacie Lafayette, Aprium…), soutenue par les fonds Latour Capital et Bpifrance. Acteur de consolidation très agressif du secteur, elle vise environ 1 800 pharmacies (~10 % du marché) pour un chiffre d'affaires de l'ordre de 3,3 milliards d'euros, à échelle européenne.","site":"https://hygie31.com","adresse":"Toulouse (Haute-Garonne, 31)","region":"Occitanie (Toulouse) — national/européen","nbAdherents":"objectif ~1 800 pharmacies","actualites":[{"titre":"Rapprochement avec Pharmacorp (leader de la pharmacie traditionnelle de proximité)","date":"2024","source":"Joffe & Associés"},{"titre":"Partenariat stratégique avec le groupement Réseau Pharma Méditerranée (RPM)","date":"sept. 2025","source":"hygie31.com"},{"titre":"Intégration de Pharm'Auvergne et poursuite des consolidations (7 opérations en 3 ans)","date":"2024-2025","source":"hygie31.com / L'Essentiel de l'Éco"}]},"lesmandarins":{"type":"groupement régional","description":"Correspond à « Mandarin Groupement », groupement de pharmacies historiquement implanté en Bretagne (démarche lancée dès 2008, élargissement du réseau à partir de 2013). Regroupe ses officines selon trois critères : couverture territoriale, non-concurrence entre membres et proximité facilitant l'entraide. Officines certifiées ISO 9001 via un système qualité propre à Mandarin ; mène des campagnes de santé publique et aide les jeunes pharmaciens à s'installer.","site":"https://www.mandarin-groupement.fr","region":"Bretagne"},"mutualpharm":{"type":"groupement régional","description":"Groupement régional fondé en 2006, basé sur Lyon / Auvergne-Rhône-Alpes, réunissant plus de 85 pharmacies indépendantes attachées à la défense de leur liberté d'entreprendre. Négocie des tarifs préférentiels (médication familiale, parapharmacie, matériel médical) et livre via le labo ou une CAP partenaire. Valeurs : proximité, transparence, indépendance. Propose plus de 20 formations gratuites/an, audits merchandising, politique prix, programme de fidélité et appli de communication entre membres.","site":"https://www.mutualpharm.com","region":"Auvergne-Rhône-Alpes (Lyon)","nbAdherents":"+85 pharmacies","dirigeants":[{"nom":"Bruno Soufflet","fn":"Président fondateur (2006), décédé en 2021"}],"actualites":[{"titre":"Évolution vers une logique d'enseigne (premier pas) et renforcement des services aux adhérents","date":"2023-2024","source":"Le Moniteur des Pharmacies"}]},"ospharea":{"type":"coopérative de pharmaciens","description":"Coopérative de pharmaciens créée en 1981 (ex-CIP, devenue Ospharea en 2007), opérant sous la marque Ospharm en toute indépendance. Défend les intérêts des titulaires en développant des solutions et outils logiciels : Pharmaland (LGO), Ospharm Datastat (synchronisation/statistiques de données officine), Ospharm FSE (tiers payant), Ospharm Formation. Accompagne pharmaciens et groupements partageant ses valeurs.","site":"https://www.ospharm.com","region":"France (national)","actualites":[{"titre":"Historique : prise de participation majoritaire dans La Source Informatique","date":"2017","source":"Le Moniteur des Pharmacies"}]},"pharmavenir":{"type":"groupement régional","description":"Groupement régional créé et gouverné par des pharmaciens pour des pharmaciens, qui met en avant son dynamisme, son professionnalisme et l'implication de chaque titulaire dans un groupement convivial et performant. Réunit des pharmaciens indépendants pour mutualiser ressources et achats.","site":"http://www.pharmavenir.org","region":"France (régional)"},"pharmaxv":{"type":"groupement (centrale d'achat agile)","description":"Groupement de pharmaciens indépendants du Sud-Ouest, créé en 2017 par une bande d'amis de la faculté de pharmacie de Toulouse, inspiré par l'esprit rugby (équipe LE PORC XV) : entraide, cohésion, engagement. Réunit près de quarante officines. Négocie sur les 7 grands piliers de l'économie officinale (30+ accords labos) via une centrale d'achat agile ; propose site click&collect, programme de fidélité et outils de communication. Unifié sous la marque « Alternativ Pharma XV » depuis 2020.","site":"https://www.groupement-pharmaxv.fr (aussi alternativ-pharmaxv.fr)","region":"Sud-Ouest / Occitanie (Toulouse)","nbAdherents":"~40 officines","actualites":[{"titre":"Unification de l'identité sous la marque Alternativ Pharma XV","date":"depuis 2020","source":"alternativ-pharmaxv.fr"}]},"pharmactiv":{"type":"enseigne / réseau national","description":"Réseau/enseigne national de pharmaciens indépendants créé en 1988, filiale du grossiste-répartiteur OCP. Compte environ 1 000 à 1 200 officines réparties dans toutes les régions françaises, plus ~200 pharmacies en Belgique. Fortement orienté prévention, suivi patient et expérience client, avec des marques et espaces santé dédiés (dont Betterlife pour le maintien à domicile, la dermocosmétique et la santé naturelle) et une gamme MDD de 400+ références.","site":"https://www.mypharmactiv.fr","region":"France (national) + Belgique","nbAdherents":"~1 000-1 200 officines (France) + ~200 (Belgique)","actualites":[{"titre":"Portrait de groupement Pharmactiv (positionnement pharmacien clinicien, espaces santé)","date":"2023","source":"Revue Pharma"}]},"pharmaxial":{"type":"groupement / centrale d'achat","description":"Groupement créé en 2012, centré sur la gestion et l'optimisation de la rentabilité des officines. Négocie les meilleures conditions d'achat auprès des principaux génériqueurs et répartiteurs, et propose des services d'accompagnement : financement de projets d'agencement et de façade, solutions digitales (site web, appli), relation labos et téléconsultation.","site":"https://choisirmongroupement.com/groupement/pharmaxial","region":"France"},"rseaupharmamditerrane":{"type":"groupement régional (sans enseigne)","description":"Groupement (RPM) créé en décembre 2021 par des pharmaciens pour des pharmaciens en PACA et Corse. Réunit environ 85 pharmacies réalisant ~110 M€ de chiffre d'affaires. Promesse : développer les marges et faire gagner du temps aux adhérents tout en préservant leur liberté et leur indépendance — sans enseigne, sans stock poussé, sans obligation. Propose achats négociés, outils de gestion, solutions digitales et formations.","site":"https://groupement-rpm.fr","adresse":"PACA (SIREN 908115553)","region":"PACA & Corse","nbAdherents":"~85 pharmacies","dirigeants":[{"nom":"Eric Mollard","fn":"Co-fondateur (Docteur en pharmacie)"},{"nom":"Bruno Calissi","fn":"Co-fondateur (Docteur en pharmacie)"},{"nom":"Christophe Di Nola","fn":"Associé fondateur"},{"nom":"Thibault Bailles","fn":"Associé fondateur"}],"actualites":[{"titre":"Partenariat stratégique avec Hygie31 (Lafayette/Aprium)","date":"sept. 2025","source":"hygie31.com / Le Moniteur des Pharmacies"}]},"sudaquitainepharmaceutique":{"type":"SRA (structure de regroupement à l'achat)","description":"SAP est une SRA (structure de regroupement à l'achat) de pharmaciens indépendants fédérés autour d'une vision commune du métier, basée au Pays basque (Ustaritz). Objectif : obtenir les meilleures conditions commerciales du marché auprès des laboratoires et grossistes. Une SRA ne porte que sur les produits non remboursables et la parapharmacie. Services : plateforme informatique d'achat, communication commerciale, site de réservation d'ordonnances. Effectif 3-5 salariés.","site":"https://www.sudaquitainepharma.fr","adresse":"Quartier Hiribehere - ZAC de la Guadeloupe, 64480 Ustaritz — SIREN 521480004","region":"Nouvelle-Aquitaine (Pays basque, 64)"},"unipharm":{"type":"coopérative régionale (SRA)","description":"Unipharm Grand-Ouest est une coopérative de pharmaciens indépendants fondée en 1990, ancrée territorialement, qui accompagne de l'ordre de 130 à 350 officines selon les entités (Grand-Ouest, Loire Océan, Unipharm 33…). Modèle coopératif « des pharmaciens au service des pharmaciens » : achats mutualisés, services personnalisables, formation des équipes et suivi sur site. Membre de la fédération Apsagir (>1 000 pharmacies) pour la force de frappe nationale.","site":"https://www.unipharm.fr","region":"Grand-Ouest (Bretagne, Pays de la Loire, Nouvelle-Aquitaine)","nbAdherents":"130 à 350 pharmacies selon entité (fédération Apsagir >1000)"},"wellwelllespharmaciens":{"type":"enseigne coopérative","description":"Enseigne coopérative de pharmaciens indépendants créée en 2002, positionnée sur le segment bien-être/mieux-être. Partie de 20 pharmaciens à sa création, elle a réuni ~320 officines et se classe parmi les premiers réseaux français (6e réseau par le nombre selon Les Échos, 2022). Coopérative appartenant à ses membres, fédérée autour de la bienveillance et de l'expertise ; propose outils digitaux, plateformes d'achats optimisées, produits exclusifs, outils marketing et formation.","site":"https://www.wellandwell.fr (groupement.wellandwell.fr)","region":"France (national)","nbAdherents":"~320 officines","dirigeants":[{"nom":"Didier Maarek","fn":"Président"}],"actualites":[{"titre":"6e réseau français de pharmacies par le nombre","date":"2022","source":"Les Échos"}]},"appassociationdespharmaciens":{"type":"association professionnelle / groupement régional","description":"Association professionnelle de pharmaciens du Sud-Est (connue sous APP SUD / APP Côte d'Azur), créée en 1985. Réunit plus de 200 à 250 pharmaciens titulaires de la région Provence-Alpes-Côte d'Azur (Aix-en-Provence, Marseille, Cannes-Mandelieu, Toulon). Positionnement centré sur la formation continue des équipes officinales (sessions mensuelles animées par des médecins spécialistes et des pharmaciens) et sur des partenariats laboratoires sélectionnés, plus que sur l'achat.","site":"https://www.appmapharmacie.com/","region":"Provence-Alpes-Côte d'Azur","nbAdherents":"200 à 250 pharmaciens","actualites":[{"titre":"Séminaire du groupement APP SUD à Barcelone","source":"LinkedIn (Louis Methais)"}]},"aporega":{"type":"groupement d'achat / SAS à capital variable","description":"Groupement de pharmacies constitué en SAS à capital variable, dont l'activité est l'achat de médicaments pour le compte de ses associés et l'organisation d'actions de formation (notamment sur le conseil pharmaceutique). Structure de taille régionale basée dans le Maine-et-Loire (Pays de la Loire). Peu d'informations publiques détaillées disponibles (profil non complété sur les annuaires).","adresse":"2 Avenue des Promeniers, 49070 Beaucouzé","region":"Pays de la Loire (Maine-et-Loire)"},"ca2pharma":{"type":"groupement d'achat / structure grossiste avec programme de fidélité","description":"Structure de type groupement/achat pharmaceutique (commerce de gros B2B de produits pharmaceutiques) créée en 2019, basée à Rilhac-Rancon près de Limoges. Portée par la société LIMPHARM. Anime le programme de fidélité multi-officines CA2+ (points de fidélité sur la parapharmacie et les produits diététiques, hors monopole pharmaceutique). Petite structure (CA d'environ 177 k€ en 2024).","adresse":"8 Avenue du 14 Juillet, 87570 Rilhac-Rancon","region":"Nouvelle-Aquitaine (Haute-Vienne)","dirigeants":[{"nom":"LIMPHARM (société dirigeante)","fn":"gérance"}]},"dpgs":{"type":"coopérative / groupement d'achat","description":"DPGS (« La Pharmacie Positive »), à l'origine Douai Pharma Gestion Services, est une coopérative fondée en 1988 par des pharmaciens, initialement pour la gestion du tiers-payant, aujourd'hui étendue au-delà du Nord-Pas-de-Calais. Compte environ 165 membres dont 80 affiliés au groupement d'achat (créé en 2003). Adopte une démarche coopérative sans référencement imposé, emblème Croix Verte. Membre actif d'APSAGIR, fédération regroupant plus de 800 pharmacies via une dizaine de groupements régionaux.","site":"https://dpgs.info/","region":"Hauts-de-France (Nord, région de Douai)","nbAdherents":"~165 membres (dont ~80 en groupement d'achat)"},"evolupharm":{"type":"groupement (association loi 1901) + laboratoire","description":"EvoluPharm est un groupement pharmaceutique national parmi les plus importants, structuré en association loi 1901 doublée d'un laboratoire (MDD). Réunit environ 1 450 à 1 500 adhérents indépendants (près d'une pharmacie sur cinq comme client), avec une centrale d'achat de 3 000+ références en livraison J+1 et plus de 350 produits à sa marque. Créé il y a plus de 35 ans pour défendre l'indépendance économique et la liberté du pharmacien. Siège à Auneuil (Oise).","site":"https://groupement.evolupharm.fr/","adresse":"Auneuil (60390), Oise","region":"National (siège Oise, Hauts-de-France)","nbAdherents":"~1 450 à 1 500 adhérents","dirigeants":[{"nom":"Jean-Pierre Chulot","fn":"fondateur / président des Laboratoires EvoluPharm"},{"nom":"Pascal Geffray","fn":"président du groupement"},{"nom":"Philippe Carmona","fn":"directeur général (nommé octobre 2025)"}],"actualites":[{"titre":"Philippe Carmona nommé nouveau directeur général d'EvoluPharm, en remplacement de Marine Fourrier","date":"octobre 2025","source":"LSA Conso"},{"titre":"Croissance par intégration : deux groupements régionaux d'une cinquantaine d'adhérents chacun ont rejoint EvoluPharm","source":"Le Quotidien du Pharmacien"}]},"grap":{"type":"groupement d'achat régional (SRA/GIE)","description":"GRAP (Groupement Régional d'Activités Pharmaceutiques) est un groupement de pharmacies d'Occitanie basé à Auterive (Haute-Garonne), au sud de Toulouse. Structure ancienne (SIREN 335002101). Informations publiques très limitées (profil non renseigné sur les annuaires professionnels). À ne pas confondre avec le GRAP alimentaire (Groupement Régional Alimentaire de Proximité, région lyonnaise).","adresse":"18 route de Toulouse, 31190 Auterive","region":"Occitanie (Haute-Garonne)"},"ifmo":{"type":"coopérative (SCIC) / groupement","description":"IFMO (Initiative Française pour le Marketing Officinal) est un groupement coopératif de pharmaciens fondé en 1989 à Strasbourg. Ancré dans le Grand Est, il combine centrale d'achat et forte activité de formation (une des premières écoles de formation d'équipes officinales dès 1991, ~3 000 professionnels formés/an par une vingtaine de formateurs). Transformé en 2014 en SCIC (Société Coopérative d'Intérêt Collectif), gouvernance à 5 collèges, ouverte à d'autres professionnels de santé.","tel":"03 88 55 00 55","adresse":"6 Rue Icare, 67960 Entzheim","region":"Grand Est (Bas-Rhin)"},"lesnouvellespharmacies":{"type":"groupement / enseigne parapharmacie petits prix","description":"Groupement de pharmacies de proximité positionné sur une stratégie parapharmacie 100% petits prix, avec des offres adaptées aux périodes de l'année pour rendre la parapharmacie accessible et maintenir le lien avec les consommateurs. Basé à Biscarrosse dans les Landes (Nouvelle-Aquitaine). Informations publiques limitées sur la taille du réseau.","adresse":"Rue Salvador Dali, 40600 Biscarrosse","region":"Nouvelle-Aquitaine (Landes)"},"normandiepharma":{"type":"groupement / coopérative (aujourd'hui Groupe OPSO Santé)","description":"Normandie Pharma est l'entité historique (raison sociale GROUPE OPSO SANTE, SIREN 880430152, siège à Colombelles 14460) devenue le groupement Opso Santé, né du rapprochement de Normandie Pharma et Bretagne Pharma. Groupement de pharmacies indépendantes créé par des pharmaciens, il fédère aujourd'hui environ 125 officines et structure sa politique d'achat, de formation et de services autour de l'enseigne Opso, tout en laissant les adhérents conserver leur propre enseigne.","site":"https://www.opsosante.fr/","adresse":"Colombelles (14460), Calvados","region":"Normandie / Bretagne (siège Colombelles, Calvados)","nbAdherents":"~125 pharmacies (Opso Santé)","actualites":[{"titre":"Opso Santé consolide son identité et étend son territoire : 125 pharmacies contre 87 il y a deux ans, gestion centralisée sous l'entité unique Opso Santé","source":"Le Moniteur des Pharmacies"},{"titre":"Création d'Opso Pharma pour couvrir les régions frontalières (Eure-et-Loir, Sarthe) au-delà de la Normandie et de la Bretagne","source":"Le Moniteur des Pharmacies"}]},"otpharma":{"type":"SRA / groupement d'achat local (coopérative)","description":"Oté Pharma est un groupement 100% local de pharmacies de La Réunion, réunissant 16 pharmacies et environ 150 professionnels de santé. Structure de type SRA/coopérative dont la mission est de mutualiser les moyens des pharmaciens réunionnais pour défendre leur pouvoir d'achat et servir au mieux les patients de l'île, dans le respect des standards éthiques et de santé publique.","site":"https://www.ote-pharma.com/","adresse":"56 Rue Général de Gaulle, 97420 Le Port, La Réunion","region":"La Réunion (Océan Indien)","nbAdherents":"16 pharmacies (~150 professionnels)"},"pharmindep":{"type":"groupement de pharmaciens indépendants","description":"Pharm'Indep est un groupement de pharmaciens indépendants centré sur la négociation d'achats, l'entraide, le partage d'expériences et la formation de ses membres, avec l'objectif de préserver l'indépendance de l'exercice officinal tout en développant l'approche commerciale nécessaire à la bonne santé économique des officines. Siège à Vron (Somme, Hauts-de-France).","site":"https://www.pharmindep.fr/","adresse":"58 Départementale 1001, 80120 Vron","region":"Hauts-de-France (Somme)"},"pharmacerp":{"type":"grossiste-répartiteur coopératif et ses groupements (groupe Astera / CERP)","description":"Rattaché à CERP (coopérative d'exploitation et de répartition pharmaceutiques du groupe Astera, grossiste-répartiteur au service des officines indépendantes actionnaires depuis 1938). CERP anime plusieurs groupements de pharmaciens : Co&Pharm (créé en 2005, 700+ membres dans le Grand Ouest) et Aelia (800+ pharmacies, ainsi qu'Aelia Outre-Mer depuis 2016). Attention : « PharmaCERP » n'est pas une marque de groupement clairement identifiée en tant que telle ; il renvoie à l'activité groupement de CERP.","site":"https://www.cerpba.com/","region":"Grand Ouest / national (CERP Bretagne Atlantique, groupe Astera)"},"pharmacyal":{"type":"groupement de pharmaciens indépendants (SRA + CAP)","description":"Pharmacyal est un groupement de pharmaciens indépendants des Hauts-de-France, créé en 2009, basé à Roubaix, réunissant environ 130 membres. Valeurs : dynamisme, réactivité, proximité. Propose une offre complète : SRA (structure de regroupement à l'achat), CAP Pharma-ML (8 000+ références dont 3 500 en conditions VIP, livraisons jusqu'à 2x/semaine), merchandising, cartes de fidélité, animations, solutions digitales et formation continue.","site":"https://www.pharmacyal.com/","adresse":"Roubaix (59)","region":"Hauts-de-France (Nord)","nbAdherents":"~130 membres"},"rseausant":{"type":"groupement indépendant de pharmaciens","description":"Réseau Santé est un groupement de pharmacies indépendantes créé en 1991 en Bretagne Atlantique, leader régional (80% de ses adhérents en Bretagne) et 8e groupement national. Compte environ 270 membres et référence plus de 100 laboratoires et partenaires. Positionné comme outil d'aide à la décision sans rien imposer, il propose certification qualité des officines, coaching, outils de gestion, communication et formation. Rattaché au Groupe PHR (qui pilote aussi Pharmactiv, PHR et Pharmavie). Siège à Brest.","adresse":"Brest (29)","region":"Bretagne (siège Brest, Finistère)","nbAdherents":"~270 membres"},"sunipharma":{"type":"groupement / SRA local","description":"Sunipharma est un petit groupement de pharmacies du sud de la région parisienne, fondé en mai 2017, basé à Vitry-sur-Seine (Val-de-Marne). Réunit une dizaine d'officines et propose mutualisation des achats et conseil en gestion. Structure de petite taille (capital social 1 000 €).","site":"http://sunipharma.fr/","adresse":"Vitry-sur-Seine (94)","region":"Île-de-France (Val-de-Marne)","nbAdherents":"~une dizaine d'officines"},"unipharm33":{"type":"coopérative régionale de pharmaciens","description":"Unipharm 33 est une coopérative de pharmaciens de Gironde active depuis 1991, réunissant plus de 30 pharmaciens coopérateurs, au service de l'indépendance et du développement d'un exercice moderne et rentable. Fondée par des pharmaciens voulant aller au-delà du simple achat. Membre de la fédération Apsara, qui regroupe plus de 300 pharmacies et mutualise services et pouvoir de négociation avec 3 autres groupements régionaux. Siège à Cadillac.","site":"https://www.unipharm33.fr/","adresse":"8 place de la République, 33410 Cadillac","region":"Nouvelle-Aquitaine (Gironde)","nbAdherents":"30+ pharmaciens coopérateurs"},"appctedazur":{"type":"Association / groupement de pharmaciens régional","description":"Association Professionnelle des Pharmaciens (aussi 'APP Sud'), groupement régional créé en 1985 qui réunit et représente plus de 200 à 250 pharmaciens titulaires sur l'ensemble de la région Provence-Côte d'Azur (Aix-en-Provence, Cannes-Mandelieu, Marseille, Toulon, Nice). Son cœur d'activité est l'accompagnement, la représentation et la formation continue mensuelle des adhérents (interventions de médecins spécialistes et pharmaciens responsables de gammes). Partenaire répartiteur historique : CERP Rhin Rhône Méditerranée.","site":"appcotedazur.com / appmapharmacie.com","region":"Provence-Alpes-Côte d'Azur (Sud)","nbAdherents":"200 à 250+ pharmacies","dirigeants":[{"nom":"Louis Methais","fn":"figure/animateur du groupement APP Sud (mention publique LinkedIn)"}],"actualites":[{"titre":"Séminaire des pharmaciens APP Sud à Barcelone","date":"récent","source":"LinkedIn (Louis Methais)"},{"titre":"Positionnement 'APP Sud' regroupant Provence + Côte d'Azur, partenariat exclusif CERP Rhin Rhône Méditerranée pour sécuriser l'approvisionnement (labos ou représentants officiels sur territoire français)","source":"pharmatheque.com / appcotedazur.com"}]},"apothera":{"type":"Groupement de pharmacies (racheté par la coopérative Giropharm)","description":"Groupement de pharmacies créé en 2017 (ex-PSD Groupe), basé à Marseille, qui fédère quatre groupements historiques (Pharma Group Santé, G1000 Pharmacies, Nepenthès, Optipharm), deux enseignes (Pure Pharmacie, Nepenthes), une MDD (NEP La Marque), un organisme de formation (Pharmacade) et une marketplace Click & Collect (Pharmizz). Il apporte à ses adhérents une CAP (Optipharm), une SRA (SRA Apothera), du merchandising et 130+ accords laboratoires. Environ 1 300 à 1 630 adhérents ; abonnement ~49 €/mois.","site":"apothera.fr","email":"contact@apothera.fr","tel":"01 39 31 67 76","adresse":"20 traverse de la Buzine, La Roseraie, Bât B2, 13011 Marseille","region":"National (siège Marseille)","nbAdherents":"1 300 à 1 634 adhérents","dirigeants":[{"nom":"Julien Daou","fn":"dirigeant Apothera"},{"nom":"Stephan Odier","fn":"dirigeant Apothera"}],"actualites":[{"titre":"Rachat d'Apothera par la coopérative Giropharm (première fois qu'une coopérative rachète des parts à des fonds d'investissement)","date":"septembre 2024","source":"Le Moniteur des Pharmacies / Le Quotidien du Pharmacien"},{"titre":"La nouvelle entité Giropharm+Apothera représente ~1 800 pharmacies partenaires, ~4 Md€ de CA cumulé, 9,2 pts de part de marché ; Daou et Odier restent aux côtés de Gilles Unglik et Luc Priouzeau (Giropharm)","date":"2024-2026","source":"Le Moniteur des Pharmacies"}]},"cabgpharmacie":{"type":"Petite structure locale / SPFPL (regroupement de 3 officines) — PAS un groupement national","description":"Ce n'est pas un groupement au sens réseau national : CABG est une SPFPL SAS (Société de Participations Financières de Professions Libérales) créée fin 2013/début 2014 à Tarare (Rhône), qui réunit trois officines d'une même ville : Pharmacie République, Pharmacie Girin et Pharmacie Blanc. Structure capitalistique locale de mutualisation entre pharmacies, pas un groupement d'achat ouvert à adhésion.","site":"cabg-pharmacie.fr","tel":"04 74 63 30 90","adresse":"48 rue de la République, 69170 Tarare","region":"Auvergne-Rhône-Alpes (Tarare, 69)","nbAdherents":"3 officines","actualites":[{"titre":"SIREN 799 085 683 (SPFPL SAS créée le 03/12/2013)","source":"societe.com / annuaire-entreprises.data.gouv.fr"}]},"directlabo":{"type":"Groupement de pharmacies / centrale d'achat (Groupe DL Santé)","description":"Groupement créé en 2001, aujourd'hui Groupe DL Santé, présent sur toute la France avec environ 1 825 officines adhérentes. Il exploite les enseignes Pharméco et Pharm&Price. Comme son nom l'indique, il privilégie l'achat direct auprès des laboratoires (partenariats labos, répartiteurs et short-liners) et propose une offre 360° : achats, audit, concentration de données, site web/marketing digital, applications mobiles, merchandising, services optique.","site":"directlabo.com","adresse":"20 rue Contrescarpe, 44000 Nantes","region":"National (siège Nantes)","nbAdherents":"~1 825 pharmacies"},"excelpharma":{"type":"Groupement de pharmacies (sans engagement, avec MDD)","description":"Groupement fondé en 2011 par des pharmaciens amis, qui revendique environ 167 à 170+ officines adhérentes en Île-de-France, Oise, Normandie et Est de la France. Offre simple et sans engagement de durée, avec 109 laboratoires référencés en direct et 53 via sa SRA. Il porte la MDD 'Pharmasoins'. Cotisation annuelle ~125 € HT.","site":"excel-pharma.fr","email":"contact@excel-pharma.fr","tel":"09 51 01 70 62","adresse":"8 rue Soddy, 94000 Créteil","region":"Île-de-France, Oise, Normandie, Est (siège Créteil)","nbAdherents":"~167 à 170 pharmacies","dirigeants":[{"nom":"Laurent Toledano","fn":"Président"}]},"gieapogie":{"type":"GIE (Groupement d'Intérêt Économique) de pharmacies","description":"GIE créé le 14 février 2022, basé à Lyon, spécialisé dans la négociation commerciale et l'achat groupé auprès des fournisseurs, laboratoires, répartiteurs et génériqueurs pour le compte de ses membres. Il assure la revente aux adhérents, des services mutualisés, la structuration de méthodes communes et l'organisation de séminaires/formations. Réseau à dominante lyonnaise/régionale (officines type Pharmacie JBS, du Cours, Quentin, Isalya, du Théâtre de Villeurbanne, du Totem, du 9ème).","adresse":"255 avenue Lacassagne, 69003 Lyon","region":"Auvergne-Rhône-Alpes (Lyon)","nbAdherents":"réseau local d'officines (petite taille)","dirigeants":[{"nom":"Lionel Amsellem","fn":"Président du conseil d'administration"}],"actualites":[{"titre":"SIREN 910 323 831, GIE actif depuis le 14/02/2022","source":"societe.com / pappers.fr"}]},"gripamelprosant":{"type":"Groupement de pharmacies régional (GIE)","description":"Groupement Indépendant des Pharmaciens du Maine-et-Loire, créé à la fin des années 1970 par quatre pharmaciens d'Angers, devenu 'Gripamel Pro Santé' (Professionnalisme, Service, Proximité). Groupement de proximité de plus de 40 ans réunissant une vingtaine d'officines en Maine-et-Loire. Il apporte achats groupés, solutions de gestion, merchandising et formation continue.","site":"gripamel.fr","email":"contact@gripamel.fr","tel":"02 41 66 57 86","adresse":"Centre commercial Jean XXIII, 49000 Angers","region":"Pays de la Loire (Maine-et-Loire / Angers)","nbAdherents":"une vingtaine d'officines","actualites":[{"titre":"Entité juridique : GIE des Pharmaciens de Maine-et-Loire (Saint-Léger-de-Linières)","source":"manageo.fr"}]},"instapharm":{"type":"Plateforme / réseau en ligne de pharmacies (à distinguer du groupement iPharm)","description":"InstaPharm (instapharm.fr, espace 'Mon Espace Pharma') se présente comme une plateforme/réseau en ligne fédérant un grand nombre de pharmacies en France (revendiquant plus de 5 000 officines). Positionnement plutôt agrégateur de services en ligne que groupement coopératif classique. Attention à ne pas le confondre avec 'iPharm', groupement/enseigne distinct créé en 2009 (Paris/IDF, ~47 adhérents). Informations de contact et gouvernance d'InstaPharm non confirmées de façon fiable (site inaccessible lors de la vérification).","site":"instapharm.fr","region":"National (à confirmer)","nbAdherents":"revendique 5 000+ pharmacies (à confirmer)"},"lesofficinales":{"type":"Groupement de pharmaciens indépendants (réseau + label)","description":"Groupement de pharmacies indépendantes attaché à l'indépendance du pharmacien, sans politique d'édit ni flux forcé ni adhésion coûteuse. Il propose parmi les meilleures conditions commerciales de France et une double approche : le RÉSEAU (conditions d'achat + outils) et le LABEL (développement de l'exercice, merchandising, spécialisation). Il dispose d'une académie de formation, d'outils de fidélisation et de partenaires spécialisés. Membre de la fédération APSAGIR aux côtés de Pharma Sud, Unipharm Gironde, Unipharm Normandie-IDF, etc. Forte présence PACA et Corse.","site":"lesofficinales.fr","region":"PACA / Corse et au-delà","actualites":[{"titre":"Regroupement au sein de la fédération APSAGIR (Les Officinales, Pharma Sud, Unipharm Gironde, Unipharm Normandie-IDF...)","source":"lesofficinales.fr / PharmaPex"}]},"norpharma":{"type":"Groupement de pharmaciens indépendants","description":"Groupement fondé en 2014 par 7 pharmaciens, comptant près de 60 adhérents. Présent en Hauts-de-France, Île-de-France, Normandie et Rhône-Alpes, il se positionne sur des valeurs de proximité, sincérité et transparence, en garantissant l'indépendance vis-à-vis des acteurs de l'industrie. Il a lancé en 2021 l'offre 'MyPharmacy'. Équipe composée de spécialistes du générique, de la répartition, de la formation et du point de vente.","site":"norpharma.net","tel":"03 22 22 53 60","adresse":"14 rue du Fossé Warin, 80080 Amiens","region":"Hauts-de-France, IDF, Normandie, Rhône-Alpes (siège Amiens)","nbAdherents":"~60 adhérents","actualites":[{"titre":"Création de l'offre 'MyPharmacy'","date":"2021","source":"norpharma.net / choisirmongroupement.com"}]},"pcd":{"description":"Aucune information fiable trouvée : 'PCD' n'a pas pu être identifié de façon certaine comme un groupement de pharmacies (absent des annuaires labodata/choisirmongroupement consultés). Sigle ambigu à faire préciser (nom complet, région) avant recherche complémentaire."},"pharmupp":{"type":"Groupement de pharmaciens indépendants (SAS, 100% pharmaciens titulaires)","description":"Union de Professionnels de la Pharmacie créée en 1987, aujourd'hui l'un des plus grands groupements de France. Il fédère environ 1 200 pharmacies réparties sur un tiers du territoire, pour un CA d'environ 2,3 milliards d'euros. Depuis 2002, les entités locales sont réunies dans la SAS Pharm-UPP, dont le capital est détenu à 100% par des pharmaciens titulaires (1 membre = 1 action) — gage d'indépendance face à la financiarisation. Valeurs : Accueil, Écoute, Conseil.","site":"pharm-upp.fr","region":"National (un tiers du territoire)","nbAdherents":"~1 200 pharmacies","actualites":[{"titre":"Nouvelle identité visuelle pour 'redessiner la pharmacie indépendante'","date":"2024-2025","source":"Le Moniteur des Pharmacies"}]},"pharmacorp":{"type":"Groupement de pharmaciens indépendants (sans enseigne, sans engagement)","description":"Groupement de pharmaciens indépendants présent dans toute la France (parfois présenté comme leader de la pharmacie traditionnelle de proximité), comptant plus de 500 adhérents et 13+ ans d'existence. Modèle sans enseigne, sans engagement, sans obligation de commande, sans cotisation : services offerts (CAP, Offisanté, formations Formacorp, Vias) ou négociés au meilleur prix. Accès à 8 gammes MDD exclusives, 120 partenaires référencés, 25 000 références sur Hygiestore, back-office gratuit. Adossé au groupe Hygie31.","site":"pharmacorp.fr","adresse":"Toulouse (31)","region":"National (siège Toulouse)","nbAdherents":"500+ adhérents","actualites":[{"titre":"Rapprochement PharmaCorp / Hygie31 (Groupe Hygie31)","date":"2024-2025","source":"Joffe & Associés / Hygie31"},{"titre":"Intégration des 32 pharmacies mutualistes du GAM (Groupement d'Achat Mutualiste) dans PharmaCorp — première fois que des pharmacies du réseau mutualiste rejoignent un groupement privé national","date":"janvier 2026","source":"Le Moniteur des Pharmacies / Hygie31"}]},"pharmadinina":{"type":"Groupement de pharmacies régional (SAS)","description":"Groupement de pharmacies de la Martinique, constitué en SAS, réunissant 41 officines réparties sur toute l'île, dont les titulaires sont associés. Créé par des pharmaciens martiniquais pour proposer des prix très compétitifs aux patients, avec un ancrage de proximité et de solidarité.","site":"pharmadinina.com","tel":"05 96 58 96 34","adresse":"3 quartier Anse Gouraud, 97233 Schoelcher (Martinique)","region":"Martinique (Antilles / Outre-mer)","nbAdherents":"41 officines","actualites":[{"titre":"Entité : SAS Pharmadinina (Le Lamentin), SIREN 804 874 527","source":"societe.com / pappers.fr"}]},"pharmidee":{"type":"Groupement de pharmacies (autonomie/transparence) — membre du 'Cartel' et de l'alliance Evecial","description":"Réseau/groupement créé par un fondateur fort de 30+ ans d'expérience dans l'industrie pharmaceutique, principalement implanté en Occitanie. Il privilégie l'autonomie : les pharmaciens décident et bâtissent en petits groupes leur politique commerciale et leurs services, avec un accompagnement expert (répartition, marché du générique, conditions transparentes, optimisation de l'officine). Fait partie du holding 'Le Cartel' (avec P&P, Katalys, Orphie-lim) — ~280 officines — et est membre de l'alliance Evecial depuis septembre 2025.","region":"Occitanie","nbAdherents":"~280 officines via le holding 'Le Cartel'","actualites":[{"titre":"Adhésion à l'alliance Evecial","date":"septembre 2025","source":"choisirmongroupement.com"},{"titre":"Membre fondateur du 'Cartel', premier 'groupement de groupements' (Pharmidée, P&P, Katalys, Orphie-lim)","source":"Le Moniteur des Pharmacies / Le Quotidien du Pharmacien"}]},"rsonor":{"type":"Groupement de pharmacies coopératif (SA Coopérative)","description":"Résonor (Résonor Soprophar), groupement/coopérative de pharmacies (SA Coopérative) créé en 1992, basé à Ronchin, comptant environ 430 adhérents principalement dans les Hauts-de-France et au-delà. Il garantit contractuellement la redistribution d'au moins 85% des honoraires perçus des partenaires (transparence et optimisation des marges des adhérents) et compte plus de 30 laboratoires référencés.","site":"groupement-resonor.fr","tel":"03 20 52 53 80","adresse":"230 avenue Jean Jaurès, 2e étage, 59790 Ronchin","region":"Hauts-de-France (siège Ronchin)","nbAdherents":"~430 adhérents"},"suprapharm":{"type":"Groupement de pharmaciens indépendants (national)","description":"Réseau national de pharmacies créé en 2014 par des pharmaciens titulaires, réunissant environ 100 à 160+ officines (plus de 500 professionnels) pour un CA d'environ 300 M€. Valeurs : partage, transparence, indépendance. Modèle où toutes les conditions et RFA sont reversées directement aux adhérents (rien ne transite par le groupement) ; les budgets marketing/communication des fournisseurs financent le groupement. Services : solutions d'achat, back-office, accompagnement à l'installation.","site":"suprapharm.fr","adresse":"108 rue Marius Aufan, 92300 Levallois-Perret","region":"National (siège Levallois-Perret)","nbAdherents":"~100 à 160 pharmacies"},"unipharmbassenormandie":{"type":"Groupement de pharmacies régional (membre de la fédération APSARA)","description":"Groupement régional de pharmacies implanté en Basse-Normandie (siège à Bayeux, Calvados), membre de la fédération APSARA. APSARA, créée en 1997, fédère plus de 600 pharmacies au sein de 7 groupements et promeut une pharmacie de proximité et de qualité soutenant l'indépendance des pharmaciens. Unipharm Basse-Normandie apporte à ses adhérents locaux les services mutualisés de cette fédération.","adresse":"24 rue des Chanoines, 14400 Bayeux","region":"Normandie (Basse-Normandie / Bayeux, 14)","nbAdherents":"groupement régional au sein d'APSARA (600+ pharmacies fédérées)"}};
